SELECT ?yearMonth (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  {
    SELECT ?investor
    WHERE {
      ?investor a wm:Investor .
      {
        SELECT ?investor (AVG(xsd:decimal(?progress)) AS ?avgProgress)
        WHERE {
          ?investor wm:hasInvestmentGoal ?goal .
          ?goal wm:progressPct ?progress .
        }
        GROUP BY ?investor
        HAVING (xsd:decimal(?avgProgress) < 50)
      }
      ?investor wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScore .
      FILTER (xsd:decimal(?riskScore) > 70)
    }
  }
  ?investor wm:hasCashFlow ?cf .
  ?cf wm:date ?date ;
      wm:amount ?amount .
  BIND (SUBSTR(?date, 1, 7) AS ?yearMonth)
  FILTER (STRSTARTS(?yearMonth, "2025-"))
}
GROUP BY ?yearMonth
ORDER BY ?yearMonth

