SELECT ?category (AVG(xsd:decimal(?riskPressureScore)) AS ?avgRiskPressureScore)
WHERE {
  ?ph a wm:PortfolioHealth ;
      wm:riskScore ?riskScore ;
      wm:liquidityScore ?liquidityScore ;
      wm:diversificationScore ?diversificationScore ;
      wm:healthOfInvestor ?inv .
  ?inv a wm:Investor ;
       wm:category ?category .
  BIND ( (xsd:decimal(?riskScore) + (100 - xsd:decimal(?liquidityScore)) + (100 - xsd:decimal(?diversificationScore))) AS ?riskPressureScore )
}
GROUP BY ?category
ORDER BY DESC(?avgRiskPressureScore)
LIMIT 5

