PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (SUM(?scenarioCount) AS ?totalScenarios) (AVG(?avgNewAlloc) AS ?avgNewAllocationPct) (AVG(?avgCurrAlloc) AS ?avgCurrentAllocationPct) (AVG(?avgGoalProg) AS ?avgGoalProgress) (AVG(?avgVolPct) AS ?avgVolatilityPct)
WHERE {
  ?inv a wm:Investor ;
       wm:segment ?segment .

  OPTIONAL {
    SELECT ?inv (COUNT(DISTINCT ?sr) AS ?scenarioCount) (AVG(xsd:decimal(?newAllocRaw)) AS ?avgNewAlloc) (AVG(xsd:decimal(?currAllocRaw)) AS ?avgCurrAlloc)
    WHERE {
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?newAllocRaw ;
          wm:currentAllocationPct ?currAllocRaw .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?goalProgRaw)) AS ?avgGoalProg) (AVG(xsd:decimal(?volPctRaw)) AS ?avgVolPct)
    WHERE {
      ?inv wm:hasInvestmentGoal ?ig .
      ?ig wm:progressPct ?goalProgRaw ;
          wm:avgVolatilityPct ?volPctRaw .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?segment
ORDER BY ?segment

