PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
  FILTER NOT EXISTS { ?inv wm:riskTolerance ?rtLiteral . }
  FILTER NOT EXISTS { ?inv wm:hasRiskTolerance ?rtObject . }
