PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?score
WHERE {
  # Investor basic info
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  # Portfolio health aggregates (riskScore, liquidityScore)
  {
    SELECT ?investorId (MAX(xsd:decimal(?riskScore)) AS ?riskScore) (MAX(xsd:decimal(?liquidityScore)) AS ?liquidityScore)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore .
    }
    GROUP BY ?investorId
  }

  # Allocation concentration (sum of allocationPct)
  {
    SELECT ?investorId (SUM(xsd:decimal(?allocationPct)) AS ?allocConcentration)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investorId
  }

  # Goal volatility (average of avgVolatilityPct)
  {
    SELECT ?investorId (AVG(xsd:decimal(?avgVolatilityPct)) AS ?goalVolatility)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:avgVolatilityPct ?avgVolatilityPct .
    }
    GROUP BY ?investorId
  }

  # Scenario change (sum of newAllocationPct - currentAllocationPct)
  {
    SELECT ?investorId (SUM(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?scenarioChange)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:newAllocationPct ?newAllocationPct ;
          wm:currentAllocationPct ?currentAllocationPct .
    }
    GROUP BY ?investorId
  }

  # Compute the five‑table risk‑pressure score
  BIND( (?riskScore + ?allocConcentration + ?goalVolatility - ?liquidityScore + ?scenarioChange) AS ?score )
}
ORDER BY DESC(?score)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(xsd:decimal(?netCashFlow)) AS ?totalNetCashFlow)
       (AVG(xsd:decimal(?goalProgress)) AS ?avgGoalProgress)
       (AVG(xsd:decimal(?holdingGain)) AS ?avgHoldingGain)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
       (AVG(xsd:decimal(?allocationConcentration)) AS ?avgAllocationConcentration)
WHERE {
  ?inv a wm:Investor .
  ?inv wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?netCashFlow)
    WHERE {
      ?cf wm:cashFlowOfInvestor ?inv .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?prog)) AS ?goalProgress)
    WHERE {
      ?goal wm:belongsToInvestor ?inv .
      ?goal wm:progressPct ?prog .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?gain)) AS ?holdingGain)
    WHERE {
      ?hold wm:heldByInvestor ?inv .
      ?hold wm:returnsPct ?gain .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?rs)) AS ?riskScore)
    WHERE {
      ?ph wm:healthOfInvestor ?inv .
      ?ph wm:riskScore ?rs .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?allocPct)) AS ?allocationConcentration)
    WHERE {
      ?alloc wm:allocationOfInvestor ?inv .
      ?alloc wm:allocationPct ?allocPct .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

