PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryName ?rebalanceName (SUM(?cashSum2025) AS ?netCashFlow2025) (AVG(?goalAvg) AS ?avgProgressPct)
WHERE {
  ?inv a wm:Investor .

  OPTIONAL {
    ?inv wm:hasCategory ?cat .
    ?cat rdfs:label ?categoryLabel .
    BIND(?categoryLabel AS ?categoryName)
  }
  BIND(COALESCE(?categoryName, "Unspecified") AS ?categoryName)

  OPTIONAL {
    ?inv wm:hasRebalancingAction ?rebAct .
    ?rebAct wm:hasRebalancingLogic ?reb .
    ?reb rdfs:label ?rebalanceLabel .
    BIND(?rebalanceLabel AS ?rebalanceName)
  }
  BIND(COALESCE(?rebalanceName, "Unspecified") AS ?rebalanceName)

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?cashSum2025)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amount ;
          wm:date ?date .
      FILTER(STRSTARTS(?date, "2025"))
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?progressPct)) AS ?goalAvg)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?categoryName ?rebalanceName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasRebalancingAction ?ra .
  ?ra wm:action ?action .
  FILTER(LCASE(STR(?action)) = "sell")
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol
       (SUM(xsd:decimal(COALESCE(?sectorAllocPct, "0"))) AS ?totalSectorAllocationPct)
       (SUM(xsd:decimal(COALESCE(?cashAmt, "0"))) AS ?totalCashFlowAmount)
       (AVG(xsd:decimal(COALESCE(?goalProg, "0"))) AS ?averageGoalProgressPct)
       (AVG(xsd:decimal(COALESCE(?scenarioDelta, "0"))) AS ?averageScenarioChangePct)
       (SUM(xsd:decimal(COALESCE(?rebalanceAmt, "0"))) AS ?totalRebalancingAmount)
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:riskTolerance ?riskTol . }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?allocPct)) AS ?sectorAllocPct)
    WHERE {
      ?inv wm:hasSectorAllocation ?sa .
      ?sa wm:allocationPct ?allocPct .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?cfAmt)) AS ?cashAmt)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmt .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?prog)) AS ?goalProg)
    WHERE {
      ?inv wm:hasInvestmentGoal ?ig .
      ?ig wm:progressPct ?prog .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?delta)) AS ?scenarioDelta)
    WHERE {
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?new .
      ?sr wm:currentAllocationPct ?cur .
      BIND(xsd:decimal(?new) - xsd:decimal(?cur) AS ?delta)
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?raAmt)) AS ?rebalanceAmt)
    WHERE {
      ?inv wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?raAmt .
    } GROUP BY ?inv
  }
}
GROUP BY ?riskTol
ORDER BY ?riskTol

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a kg:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?totalCash)
    WHERE {
      ?cf a kg:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
    }
    GROUP BY ?inv
    HAVING (?totalCash > 100000000)
  }

  {
    SELECT ?inv (AVG(xsd:decimal(?prog)) AS ?avgProg)
    WHERE {
      ?ig a kg:InvestmentGoal ;
          wm:belongsToInvestor ?inv ;
          wm:progressPct ?prog .
    }
    GROUP BY ?inv
    HAVING (?avgProg < 25)
  }

  {
    SELECT ?inv (MAX(xsd:decimal(?riskScore)) AS ?maxRisk)
    WHERE {
      ?ph a kg:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:riskScore ?riskScore .
    }
    GROUP BY ?inv
    HAVING (?maxRisk > 70)
  }

  {
    SELECT ?inv (AVG(xsd:decimal(?change)) AS ?avgChange)
    WHERE {
      ?sr a kg:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?inv ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
      BIND ((xsd:decimal(?new) - xsd:decimal(?cur)) AS ?change)
    }
    GROUP BY ?inv
    HAVING (?avgChange > 20)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:category ?cat ;
       wm:hasPortfolioHealth ?ph ;
       wm:hasHolding ?hold .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER(LCASE(STR(?cat)) = "debt")

  ?ph wm:liquidityScore ?liqScore .
  FILTER(xsd:decimal(?liqScore) < 40)

  ?hold wm:hasSector ?sector .
  ?sector rdfs:label ?sectorLabel .
  FILTER(CONTAINS(LCASE(STR(?sectorLabel)), "healthcare"))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel
       (AVG(?goalProgress) AS ?avgGoalProgressPct)
       (SUM(?holdingGain) AS ?totalHoldingGain)
       (AVG(?riskScore) AS ?avgRiskScore)
       (AVG(?liquidityScore) AS ?avgLiquidityScore)
WHERE {
  {
    SELECT ?investor ?category ?categoryLabel
           (SUM(xsd:decimal(?currVal) - xsd:decimal(?cost)) AS ?holdingGain)
           (AVG(xsd:decimal(?goalProg)) AS ?goalProgress)
           (AVG(xsd:decimal(?risk)) AS ?riskScore)
           (AVG(xsd:decimal(?liq)) AS ?liquidityScore)
    WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:heldByInvestor ?investor ;
            wm:hasCategory ?category ;
            wm:currentValue ?currVal ;
            wm:cost ?cost .
      ?category rdfs:label ?categoryLabel .
      OPTIONAL {
        ?goal a wm:InvestmentGoal ;
              wm:belongsToInvestor ?investor ;
              wm:progressPct ?goalProg .
      }
      OPTIONAL {
        ?health a wm:PortfolioHealth ;
                wm:healthOfInvestor ?investor ;
                wm:riskScore ?risk ;
                wm:liquidityScore ?liq .
      }
    }
    GROUP BY ?investor ?category ?categoryLabel
  }
}
GROUP BY ?categoryLabel
ORDER BY ?categoryLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?inv wm:hasCashFlow ?cf .
    ?cf wm:hasCashFlowSource ?cfs .
    ?cfs rdfs:label ?cfsLabel .
    FILTER(CONTAINS(LCASE(STR(?cfsLabel)), "systematic"))
  }

  FILTER EXISTS {
    ?inv wm:hasRebalancingAction ?ra .
    ?ra wm:hasRebalancingLogic ?rl .
    ?rl rdfs:label ?rlLabel .
    FILTER(CONTAINS(LCASE(STR(?rlLabel)), "calendar-based"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?riskScore
WHERE {
  # Investors with a sector allocation > 40%
  {
    SELECT DISTINCT ?inv WHERE {
      ?alloc a wm:SectorAllocation ;
             wm:allocationOfInvestor ?inv ;
             wm:allocationPct ?allocPct .
      FILTER(xsd:decimal(?allocPct) > 40)
    }
  }
  # Investors with at least one negative‑return holding
  {
    SELECT DISTINCT ?inv WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:heldByInvestor ?inv ;
            wm:returnsPct ?ret .
      FILTER(xsd:decimal(?ret) < 0)
    }
  }
  # Portfolio health (risk score) for the qualifying investors
  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?inv ;
      wm:riskScore ?riskScore .
  ?inv wm:investorId ?investorId ;
       wm:investorName ?investorName .
}
ORDER BY DESC(xsd:decimal(?riskScore))
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName ?riskScore ?liquidityScore
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:hasPortfolioHealth ?ph .
  OPTIONAL { ?investor wm:investorName ?investorName . }
  ?ph wm:riskScore ?riskScore ;
      wm:liquidityScore ?liquidityScore .
  FILTER ( xsd:decimal(?riskScore) > 70 && xsd:decimal(?liquidityScore) < 30 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorLabel ?avgReturnsPct ?avgDiversificationScore
WHERE {
  {
    SELECT ?sector ?sectorLabel (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnsPct)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:hasSector ?sector ;
               wm:returnsPct ?returnsPct .
      ?sector rdfs:label ?sectorLabel .
    }
    GROUP BY ?sector ?sectorLabel
  }
  {
    SELECT ?sector ?sectorLabel (AVG(xsd:decimal(?divScore)) AS ?avgDiversificationScore)
    WHERE {
      {
        SELECT DISTINCT ?investorId ?sector ?sectorLabel
        WHERE {
          ?holding a wm:PortfolioHolding ;
                   wm:investorId ?investorId ;
                   wm:hasSector ?sector .
          ?sector rdfs:label ?sectorLabel .
        }
      }
      ?ph a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:diversificationScore ?divScore .
    }
    GROUP BY ?sector ?sectorLabel
  }
}
ORDER BY ?sectorLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (AVG(?avgProgress) AS ?avgGoalProgress) (AVG(?riskScore) AS ?avgRiskScore) (SUM(?totalHolding) AS ?totalHoldingValue)
WHERE {
  ?investor wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    SELECT ?investor (AVG(?progressPct) AS ?avgProgress)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPct .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (AVG(?riskScoreVal) AS ?riskScore)
    WHERE {
      ?investor wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScoreVal .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    SELECT ?investor (SUM(?currentValue) AS ?totalHolding)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:currentValue ?currentValue .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month (AVG(xsd:decimal(?liqScore)) AS ?avgLiquidityScore)
WHERE {
  {
    SELECT DISTINCT ?investor ?month WHERE {
      ?cf a wm:CashFlow ;
          wm:date ?date ;
          wm:cashFlowOfInvestor ?investor .
      BIND(STR(?date) AS ?dateStr)
      FILTER(STRSTARTS(LCASE(?dateStr), "2025-"))
      BIND(SUBSTR(?dateStr, 1, 7) AS ?month)   # YYYY-MM
    }
  }
  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:liquidityScore ?liqScore .
}
GROUP BY ?month
ORDER BY ?month

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goalId ?description ?progressPct
WHERE {
  ?ig a wm:InvestmentGoal ;
      wm:goalId ?goalId ;
      wm:description ?description ;
      wm:progressPct ?progressPct .
  FILTER(xsd:decimal(?progressPct) < 25)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgProgress ?totalHoldingGain ?netCashFlow ?riskScore
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 180)

  {
    SELECT ?inv (AVG(xsd:decimal(?pg)) AS ?avgProgress)
    WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?pg .
    }
    GROUP BY ?inv
    HAVING (AVG(xsd:decimal(?pg)) < 40)
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?cv) - xsd:decimal(?c)) AS ?totalHoldingGain)
    WHERE {
      ?inv wm:hasHolding ?hold .
      ?hold wm:currentValue ?cv .
      ?hold wm:cost ?c .
    }
    GROUP BY ?inv
    HAVING (SUM(xsd:decimal(?cv) - xsd:decimal(?c)) < 0)
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?netCashFlow)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?inv
    HAVING (SUM(xsd:decimal(?amt)) < 0)
  }
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorLabel (AVG(xsd:decimal(?allocPct)) AS ?avgAllocationPct)
WHERE {
  {
    SELECT DISTINCT ?inv WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:riskScore ?riskScore ;
          wm:healthOfInvestor ?inv .
      FILTER(?riskScore > 70)
    }
  }
  ?sa a wm:SectorAllocation ;
      wm:allocationPct ?allocPct ;
      wm:allocationOfInvestor ?inv ;
      wm:hasSector ?sector .
  ?sector rdfs:label ?sectorLabel .
}
GROUP BY ?sectorLabel
ORDER BY DESC(?avgAllocationPct)
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  {
    SELECT DISTINCT ?inv WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:riskScore ?riskScore .
      FILTER(xsd:decimal(?riskScore) > 60)
    }
  }
  {
    SELECT DISTINCT ?inv WHERE {
      ?sa a wm:SectorAllocation ;
          wm:allocationOfInvestor ?inv ;
          wm:allocationPct ?allocPct .
      FILTER(xsd:decimal(?allocPct) > 20)
    }
  }
  {
    SELECT DISTINCT ?inv WHERE {
      ?phold a wm:PortfolioHolding ;
          wm:heldByInvestor ?inv ;
          wm:taxesPaid ?taxes .
      FILTER(xsd:decimal(?taxes) > 25000)
    }
  }
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?targetAmount ?currentValue WHERE {
  ?ig a wm:InvestmentGoal ;
      wm:goalId ?goalId ;
      wm:targetAmount ?targetAmount ;
      wm:currentValue ?currentValue .
  FILTER(CONTAINS(LCASE(STR(?goalId)), "0006aef2-ab21-43d6-8885-4730e21c870b"))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (SUM(xsd:decimal(COALESCE(?cashFlowSum, 0))) AS ?totalCashFlow)
       (SUM(xsd:decimal(COALESCE(?rebalanceSum, 0))) AS ?totalRebalanceAmount)
       (SUM(xsd:decimal(COALESCE(?scenarioSum, 0))) AS ?totalScenarioChange)
       (AVG(xsd:decimal(COALESCE(?riskScoreAvg, 0))) AS ?avgRiskScore)
       (AVG(xsd:decimal(COALESCE(?goalMatchAvg, 0))) AS ?avgGoalMatchPct)
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:timeHorizon ?timeHorizon .

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amount .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?raAmt)) AS ?rebalanceSum)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?inv ;
          wm:amount ?raAmt .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?newAlloc)) AS ?scenarioSum)
    WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?inv ;
          wm:newAllocationPct ?newAlloc .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?riskScore)) AS ?riskScoreAvg)
                     (AVG(xsd:decimal(?goalMatchPct)) AS ?goalMatchAvg)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:riskScore ?riskScore ;
          wm:goalMatchPct ?goalMatchPct .
      ?inv wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?rebalanceAmt) AS ?totalRebalanceAmount)
       (SUM(?rebalanceCount) AS ?rebalanceTransactionCount)
       (SUM(?cashAmt) AS ?totalCashFlowAmount)
       (SUM(?cashCount) AS ?cashTransactionCount)
WHERE {
  {
    SELECT ?riskTolerance (SUM(xsd:decimal(?raAmt)) AS ?rebalanceAmt) (COUNT(?ra) AS ?rebalanceCount)
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?inv ;
          wm:amount ?raAmt .
      ?inv wm:riskTolerance ?riskTolerance .
    }
    GROUP BY ?riskTolerance
  }
  UNION
  {
    SELECT ?riskTolerance (SUM(xsd:decimal(?cfAmt)) AS ?cashAmt) (COUNT(?cf) AS ?cashCount)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?cfAmt .
      ?inv wm:riskTolerance ?riskTolerance .
    }
    GROUP BY ?riskTolerance
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cashFlowTypeLabel ?totalCashFlowAmount ?totalRebalancingAmount WHERE {
  {
    SELECT ?cashFlowType (SUM(xsd:decimal(?cfAmt)) AS ?totalCashFlowAmount) WHERE {
      ?cf a wm:CashFlow ;
          wm:hasCashFlowType ?cashFlowType ;
          wm:amount ?cfAmt .
    } GROUP BY ?cashFlowType
  }
  {
    SELECT (SUM(xsd:decimal(?rebAmt)) AS ?totalRebalancingAmount) WHERE {
      ?reb a wm:RebalancingAction ;
           wm:amount ?rebAmt .
    }
  }
  OPTIONAL { ?cashFlowType rdfs:label ?cashFlowTypeLabel . }
}
ORDER BY ?cashFlowTypeLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?scenarioChange) AS ?avgScenarioChange)
       (AVG(?gap) AS ?avgRebalancingGap)
       (SUM(?totalAmount) AS ?totalRebalancingAmount)
WHERE {
  ?inv a wm:Investor ;
       wm:category ?category .

  {
    SELECT ?inv (AVG(xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?scenarioChange)
                 (AVG(xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?gap)
    WHERE {
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?newPct ;
          wm:currentAllocationPct ?curPct .
    }
    GROUP BY ?inv
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?totalAmount)
    WHERE {
      ?inv wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?amount .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segment (SUM(?profileCount) AS ?profileCount) (SUM(?holdingCount) AS ?holdingCount)
WHERE {
  {
    SELECT ?segment (COUNT(DISTINCT ?inv) AS ?profileCount)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:segment ?segment .
    }
    GROUP BY ?segment
  }
  UNION
  {
    SELECT ?segment (COUNT(DISTINCT ?hold) AS ?holdingCount)
    WHERE {
      ?hold a wm:PortfolioHolding .
      ?hold wm:segment ?segment .
    }
    GROUP BY ?segment
  }
}
GROUP BY ?segment
ORDER BY ?segment

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?riskTolerance ?diversificationScore ?goalMatchPct ?liquidityScore ?riskScore
WHERE {
  ?investor wm:investorId ?invId .
  FILTER(CONTAINS(LCASE(STR(?invId)), "inv-001"))
  OPTIONAL { ?investor wm:investorName ?investorName . }
  OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }
  OPTIONAL {
    ?investor wm:hasPortfolioHealth ?ph .
    OPTIONAL { ?ph wm:diversificationScore ?diversificationScore . }
    OPTIONAL { ?ph wm:goalMatchPct ?goalMatchPct . }
    OPTIONAL { ?ph wm:liquidityScore ?liquidityScore . }
    OPTIONAL { ?ph wm:riskScore ?riskScore . }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?scenario ?action (AVG(xsd:decimal(?change)) AS ?avgChange)
WHERE {
  ?sr wm:scenario ?scenario ;
      wm:newAllocationPct ?newAlloc ;
      wm:currentAllocationPct ?currAlloc ;
      wm:hasTriggeredAction ?dec .
  BIND (xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc) AS ?change)
  ?ra wm:hasRebalancingDecision ?dec ;
      wm:action ?action .
}
GROUP BY ?scenario ?action
ORDER BY DESC(?avgChange)
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cashFlowTypeLabel ?action (AVG(xsd:decimal(?invAvgShortfall)) AS ?avgShortfall)
WHERE {
  {
    SELECT ?invId (AVG(xsd:decimal(?shortfall)) AS ?invAvgShortfall)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?invId ;
          wm:shortfall ?shortfall .
    }
    GROUP BY ?invId
  }
  {
    SELECT ?invId ?cashFlowTypeLabel
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?invId ;
          wm:hasCashFlowType ?cft .
      ?cft rdfs:label ?cashFlowTypeLabel .
    }
    GROUP BY ?invId ?cashFlowTypeLabel
  }
  {
    SELECT ?invId ?action
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:investorId ?invId ;
          wm:action ?action .
    }
    GROUP BY ?invId ?action
  }
}
GROUP BY ?cashFlowTypeLabel ?action

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?totalCashFlow ?totalScenarioChange ?scenarioCount WHERE {
  {
    SELECT (SUM(xsd:decimal(?amt)) AS ?totalCashFlow) WHERE {
      ?cf a kg:CashFlow ;
          wm:amount ?amt .
    }
  }
  {
    SELECT (SUM(xsd:decimal(?alloc)) AS ?totalScenarioChange) WHERE {
      ?sr a kg:ScenarioRebalancing ;
          wm:newAllocationPct ?alloc .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?sc) AS ?scenarioCount) WHERE {
      ?sr2 a kg:ScenarioRebalancing ;
           wm:scenario ?sc .
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cat
       (SUM(?inflow) AS ?totalInflow)
       (SUM(?outflow) AS ?totalOutflow)
       (SUM(?shortfall) AS ?totalShortfall)
       (SUM(?dividends) AS ?totalDividends)
       (SUM(?taxesPaid) AS ?totalTaxesPaid)
WHERE {
  {
    SELECT ?inv (SUM(?inAmt) AS ?inflow) (SUM(?outAmt) AS ?outflow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
      OPTIONAL { ?cf wm:type ?type . }
      BIND( IF( BOUND(?type) && LCASE(STR(?type)) = "inflow", xsd:decimal(?amt), 0 ) AS ?inAmt )
      BIND( IF( BOUND(?type) && LCASE(STR(?type)) = "outflow", xsd:decimal(?amt), 0 ) AS ?outAmt )
    }
    GROUP BY ?inv
  }
  {
    SELECT ?inv (SUM(xsd:decimal(?sf)) AS ?shortfall)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:shortfall ?sf .
    }
    GROUP BY ?inv
  }
  {
    SELECT ?inv (SUM(xsd:decimal(?div)) AS ?dividends) (SUM(xsd:decimal(?tax)) AS ?taxesPaid)
    WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:heldByInvestor ?inv .
      OPTIONAL { ?hold wm:dividends ?div . }
      OPTIONAL { ?hold wm:taxesPaid ?tax . }
    }
    GROUP BY ?inv
  }
  ?inv wm:hasCategory ?cat .
}
GROUP BY ?cat
ORDER BY ?cat

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (AVG(?invAvg) AS ?avgProgressPct)
WHERE {
  {
    SELECT ?inv (AVG(xsd:decimal(?p)) AS ?invAvg)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:progressPct ?p .
      FILTER(bound(?p))
    }
    GROUP BY ?inv
  }
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTolerance .
}
GROUP BY ?riskTolerance
ORDER BY DESC(?avgProgressPct)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?totalShortfall ?totalGain ?totalCash
WHERE {
  # Investor basic info
  ?inv a wm:Investor ;
       wm:investorName ?investorName .

  # Aggregate shortfall per investor
  {
    SELECT ?inv (SUM(xsd:decimal(?sf)) AS ?totalShortfall)
    WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:shortfall ?sf .
    }
    GROUP BY ?inv
  }

  # Aggregate holding gain per investor (currentValue - cost)
  {
    SELECT ?inv (SUM(xsd:decimal(?gain)) AS ?totalGain)
    WHERE {
      ?inv wm:hasHolding ?hold .
      ?hold wm:currentValue ?cv .
      ?hold wm:cost ?c .
      BIND (xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
    }
    GROUP BY ?inv
  }

  # Aggregate cash flow amount per investor
  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?totalCash)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?inv
  }

  FILTER ( ?totalShortfall > 0 && ?totalGain < 0 && ?totalCash < 10000 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investor ?label
WHERE {
  ?investor rdf:type wm:Investor .
  FILTER EXISTS {
    ?investor wm:hasHolding ?hold .
    ?hold wm:purchaseDate ?pdate .
    FILTER (STRSTARTS(STR(?pdate), "2025"))
  }
  FILTER EXISTS {
    ?investor wm:hasCashFlow ?cf .
    ?cf wm:date ?cdate .
    FILTER (STRSTARTS(STR(?cdate), "2025"))
  }
  OPTIONAL { ?investor rdfs:label ?label . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName WHERE {
  ?ph a wm:PortfolioHealth ;
      wm:diversificationScore ?divScore ;
      wm:healthOfInvestor ?inv .
  FILTER(xsd:decimal(?divScore) < 25)

  ?inv a wm:Investor ;
       wm:riskTolerance ?rt ;
       wm:investorName ?investorName .
  FILTER(CONTAINS(LCASE(STR(?rt)), "aggressive"))

  FILTER EXISTS { ?inv wm:hasHolding ?hold . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?avgProg ?risk ?totalWithdrawal WHERE {
  ?inv wm:investorName ?investorName .
  ?inv wm:riskTolerance ?riskStr .
  BIND(xsd:decimal(?riskStr) AS ?risk)
  FILTER(?risk > 50)

  {
    SELECT ?inv (AVG(xsd:decimal(?prog)) AS ?avgProg) WHERE {
      ?goal wm:belongsToInvestor ?inv .
      ?goal wm:progressPct ?prog .
    } GROUP BY ?inv
  }
  FILTER(?avgProg < 40)

  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?totalWithdrawal) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
      ?cf wm:type ?cfType .
      FILTER(CONTAINS(LCASE(?cfType), "withdrawal"))
    } GROUP BY ?inv
  }
}
ORDER BY DESC(?totalWithdrawal)
LIMIT 5

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:category ?cat ;
       wm:hasPortfolioHealth ?ph .
  FILTER(LCASE(STR(?cat)) = "equity")
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 80)
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasSectorAllocation ?sa ;
       wm:hasRebalancingAction ?ra ;
       wm:hasScenarioRebalancing ?sr .

  ?sa wm:allocationPct ?allocPct .
  FILTER(?allocPct > 20)

  ?ra wm:action ?raAction .
  FILTER(CONTAINS(LCASE(STR(?raAction)), "sell"))

  ?sr wm:hasMarketScenario ?ms .
  ?ms rdfs:label ?scenarioLabel .
  FILTER(CONTAINS(LCASE(STR(?scenarioLabel)), "flash crash"))

  {
    SELECT ?inv (SUM(xsd:decimal(?withdrawAmt)) AS ?totalWithdraw) (SUM(xsd:decimal(?depositAmt)) AS ?totalDeposit)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:type ?cfType ;
          wm:amount ?amt .
      BIND(xsd:decimal(?amt) AS ?decAmt)
      BIND(IF(CONTAINS(LCASE(STR(?cfType)), "withdrawal"), ?decAmt, 0) AS ?withdrawAmt)
      BIND(IF(CONTAINS(LCASE(STR(?cfType)), "deposit"), ?decAmt, 0) AS ?depositAmt)
    }
    GROUP BY ?inv
    HAVING(?totalWithdraw > ?totalDeposit)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?scenario (AVG(?gap) AS ?avgGap) (SUM(?totalAmt) AS ?totalAmount)
WHERE {
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTolerance ;
       wm:hasScenarioRebalancing ?sr .
  ?sr a wm:ScenarioRebalancing ;
       wm:scenario ?scenario ;
       wm:newAllocationPct ?newPct ;
       wm:currentAllocationPct ?currPct .
  BIND (xsd:decimal(?newPct) - xsd:decimal(?currPct) AS ?gap)

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?totalAmt)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasRebalancingAction ?ra .
      ?ra a wm:RebalancingAction ;
          wm:amount ?amt .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskTolerance ?scenario

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?investorName ?avgVol ?divScore WHERE {
  {
    SELECT ?investor (AVG(xsd:decimal(?vol)) AS ?avgVol) WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:avgVolatilityPct ?vol .
    } GROUP BY ?investor
  }
  ?investor wm:hasPortfolioHealth ?ph .
  ?ph wm:diversificationScore ?divScore .
  OPTIONAL { ?investor wm:investorName ?investorName . }
  FILTER ( ?avgVol > 30 && xsd:decimal(?divScore) < 30 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sector ?avgHoldingReturn ?totalInvestment ?avgAllocationPct
WHERE {
  {
    SELECT ?sector (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturn)
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:sector ?sector ;
               wm:returnsPct ?returnsPct .
    }
    GROUP BY ?sector
  }
  {
    SELECT ?sector (SUM(xsd:decimal(?totalInv)) AS ?totalInvestment) (AVG(xsd:decimal(?allocPct)) AS ?avgAllocationPct)
    WHERE {
      ?alloc a wm:SectorAllocation ;
            wm:sector ?sector ;
            wm:totalInvestment ?totalInv ;
            wm:allocationPct ?allocPct .
    }
    GROUP BY ?sector
  }
}
ORDER BY ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizonLabel ?totalRebalanceAmount ?totalCashFlowAmount ?avgGoalProgress ?avgShortfall
WHERE {
  {
    SELECT DISTINCT ?timeHorizonLabel ?th
    WHERE {
      ?inv a wm:Investor ;
           wm:hasTimeHorizon ?th .
      ?th rdfs:label ?timeHorizonLabel .
    }
  }

  OPTIONAL {
    SELECT ?timeHorizonLabel (SUM(xsd:decimal(?raAmt)) AS ?totalRebalanceAmount)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasTimeHorizon ?th .
      ?th rdfs:label ?timeHorizonLabel .
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?inv ;
          wm:amount ?raAmt .
    }
    GROUP BY ?timeHorizonLabel
  }

  OPTIONAL {
    SELECT ?timeHorizonLabel (SUM(xsd:decimal(?cfAmt)) AS ?totalCashFlowAmount)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasTimeHorizon ?th .
      ?th rdfs:label ?timeHorizonLabel .
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?cfAmt .
    }
    GROUP BY ?timeHorizonLabel
  }

  OPTIONAL {
    SELECT ?timeHorizonLabel (AVG(xsd:decimal(?prog)) AS ?avgGoalProgress) (AVG(xsd:decimal(?shf)) AS ?avgShortfall)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasTimeHorizon ?th .
      ?th rdfs:label ?timeHorizonLabel .
      ?ig a wm:InvestmentGoal ;
          wm:belongsToInvestor ?inv ;
          wm:progressPct ?prog ;
          wm:shortfall ?shf .
    }
    GROUP BY ?timeHorizonLabel
  }
}
ORDER BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(xsd:decimal(?cashFlowTotal)) AS ?totalCashFlow)
       (AVG(xsd:decimal(?scenarioChange)) AS ?avgScenarioChange)
       (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct)
       (SUM(xsd:decimal(?sectorInvestTotal)) AS ?totalSectorInvestment)
WHERE {
  ?investor a wm:Investor .
  ?investor wm:riskTolerance ?riskTolerance .
  FILTER(BOUND(?riskTolerance))

  {
    SELECT ?investor (SUM(xsd:decimal(?amt)) AS ?cashFlowTotal)
    WHERE {
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?change)) AS ?scenarioChange)
    WHERE {
      ?investor wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?new .
      ?sr wm:currentAllocationPct ?cur .
      BIND (xsd:decimal(?new) - xsd:decimal(?cur) AS ?change)
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?allocPct)) AS ?allocationPct)
    WHERE {
      ?investor wm:hasSectorAllocation ?sa .
      ?sa wm:allocationPct ?allocPct .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (SUM(xsd:decimal(?val)) AS ?sectorInvestTotal)
    WHERE {
      ?investor wm:hasHolding ?hold .
      ?hold wm:currentValue ?val .
    }
    GROUP BY ?investor
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?th (SUM(?txCount) AS ?transactionCount) (SUM(?holdCount) AS ?holdingCount) (SUM(?goalCount) AS ?goalCount) (SUM(?scenarioCount) AS ?scenarioCount)
WHERE {
  ?inv a wm:Investor .
  ?inv wm:hasTimeHorizon ?th .

  OPTIONAL {
    SELECT ?inv (COUNT(DISTINCT ?cf) AS ?txCount)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (COUNT(DISTINCT ?ph) AS ?holdCount)
    WHERE {
      ?inv wm:hasHolding ?ph .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (COUNT(DISTINCT ?ig) AS ?goalCount)
    WHERE {
      ?inv wm:hasInvestmentGoal ?ig .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (COUNT(DISTINCT ?ms) AS ?scenarioCount)
    WHERE {
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:hasMarketScenario ?ms .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?th

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holding ?holdingId
WHERE {
  ?holding a wm:PortfolioHolding .
  OPTIONAL { ?holding wm:holdingId ?holdingId . }
  FILTER NOT EXISTS { ?holding wm:hasSegment ?seg . }
  FILTER NOT EXISTS { ?holding wm:segment ?segLiteral . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?inv (AVG(xsd:decimal(?sharpe)) AS ?avgSharpe) (AVG(xsd:decimal(?vol)) AS ?avgVol)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:avgSharpeRatio ?sharpe ;
            wm:avgVolatilityPct ?vol .
    }
    GROUP BY ?inv
    HAVING (AVG(xsd:decimal(?sharpe)) < 0 && AVG(xsd:decimal(?vol)) > 10)
  }

  {
    SELECT ?inv ((SUM(xsd:decimal(?currVal)) - SUM(xsd:decimal(?cst))) AS ?totalHoldingGain)
    WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:heldByInvestor ?inv ;
            wm:currentValue ?currVal ;
            wm:cost ?cst .
    }
    GROUP BY ?inv
    HAVING ((SUM(xsd:decimal(?currVal)) - SUM(xsd:decimal(?cst))) < 0)
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
    }
    GROUP BY ?inv
    HAVING (SUM(xsd:decimal(?amt)) < 1000000)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?score WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  OPTIONAL {
    SELECT (SUM(xsd:decimal(?sf)) AS ?totalShortfall) WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:shortfall ?sf .
    }
  }

  OPTIONAL {
    SELECT (SUM(xsd:decimal(?cv) - xsd:decimal(?c)) AS ?totalHoldingGain) WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:heldByInvestor ?inv ;
            wm:currentValue ?cv ;
            wm:cost ?c .
    }
  }

  OPTIONAL {
    SELECT (SUM(xsd:decimal(?amt)) AS ?netCashFlow) WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
    }
  }

  OPTIONAL {
    SELECT (MAX(xsd:decimal(?rs)) AS ?riskScore) WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:riskScore ?rs .
    }
  }

  BIND( (COALESCE(?totalShortfall, 0) 
         - COALESCE(?totalHoldingGain, 0) 
         - COALESCE(?netCashFlow, 0) 
         + COALESCE(?riskScore, 0)) AS ?score )
  FILTER ( ?score > 50000000 )
}
ORDER BY DESC(?score)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:segment ?segment ;
       wm:investmentGoal ?investmentGoal ;
       wm:riskTolerance ?riskTolerance ;
       wm:sectorFocus ?sectorFocus ;
       wm:timeHorizon ?timeHorizon ;
       wm:category ?category ;
       wm:notes ?notes .
  FILTER EXISTS {
    SELECT ?inv WHERE {
      ?inv wm:hasHolding ?hold .
      OPTIONAL { ?hold wm:category ?holdCategory }
      OPTIONAL { ?hold wm:investmentType ?holdInvType }
      OPTIONAL { ?hold wm:sector ?holdSector }
      FILTER ( !BOUND(?holdCategory) || !BOUND(?holdInvType) || !BOUND(?holdSector) )
    } LIMIT 1
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?inflow) AS ?totalInflow)
       (SUM(?outflow) AS ?totalOutflow)
       (SUM(?shortfall) AS ?totalShortfall)
       (SUM(?dividends) AS ?totalDividends)
       (SUM(?taxesPaid) AS ?totalTaxesPaid)
WHERE {
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    SELECT ?inv (SUM(?inAmt) AS ?inflow) (SUM(?outAmt) AS ?outflow) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt ;
          wm:type ?type .
      BIND(xsd:decimal(?amt) AS ?amtDec)
      BIND(IF(LCASE(?type) = "inflow", ?amtDec, 0) AS ?inAmt)
      BIND(IF(LCASE(?type) = "outflow", ?amtDec, 0) AS ?outAmt)
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(?sfVal) AS ?shortfall) WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:shortfall ?sf .
      BIND(xsd:decimal(?sf) AS ?sfVal)
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(?divVal) AS ?dividends) (SUM(?taxVal) AS ?taxesPaid) WHERE {
      ?inv wm:hasHolding ?hold .
      ?hold wm:dividends ?div ;
            wm:taxesPaid ?tax .
      BIND(xsd:decimal(?div) AS ?divVal)
      BIND(xsd:decimal(?tax) AS ?taxVal)
    } GROUP BY ?inv
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasInvestmentGoal ?goal ;
            wm:hasHolding ?holding ;
            wm:hasSectorAllocation ?alloc ;
            wm:hasPortfolioHealth ?health .

  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)

  ?holding wm:returnsPct ?returnsPct .
  FILTER(xsd:decimal(?returnsPct) < 0)

  ?alloc wm:allocationPct ?allocationPct .
  FILTER(xsd:decimal(?allocationPct) > 25)

  ?health wm:diversificationScore ?divScore .
  FILTER(xsd:decimal(?divScore) < 40)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance 
       (SUM(IF(?goalCount = 1, 1, 0)) AS ?oneGoalCount) 
       (SUM(IF(?goalCount = 2, 1, 0)) AS ?twoGoalCount) 
       (SUM(IF(?goalCount = 3, 1, 0)) AS ?threeGoalCount) 
       (SUM(IF(?goalCount >= 4, 1, 0)) AS ?fourOrMoreCount)
WHERE {
  {
    SELECT ?investor ?riskTolerance (COUNT(DISTINCT ?goal) AS ?goalCount)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?riskTolerance . }
      OPTIONAL { ?investor wm:hasInvestmentGoal ?goal . }
    }
    GROUP BY ?investor ?riskTolerance
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holding ?holdingId
WHERE {
  ?holding a wm:PortfolioHolding .
  OPTIONAL { ?holding wm:holdingId ?holdingId . }
  FILTER NOT EXISTS { ?holding wm:hasSector ?sector . }
  FILTER NOT EXISTS { ?holding wm:sector ?sectorLiteral . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segmentLabel (SUM(?depositAmount) AS ?totalDeposit) (SUM(?withdrawalAmount) AS ?totalWithdrawal)
WHERE {
  {
    SELECT ?inv (SUM(?depositAmt) AS ?depositAmount) (SUM(?withdrawalAmt) AS ?withdrawalAmount)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:hasCashFlowType ?cft ;
          wm:amount ?amount .
      ?cft rdfs:label ?cftLabel .
      BIND (LCASE(STR(?cftLabel)) AS ?typeLabel)
      BIND (IF(?typeLabel = "deposit", xsd:decimal(?amount), 0) AS ?depositAmt)
      BIND (IF(?typeLabel = "withdrawal", xsd:decimal(?amount), 0) AS ?withdrawalAmt)
    }
    GROUP BY ?inv
  }
  ?inv wm:hasSegment ?seg .
  OPTIONAL { ?seg rdfs:label ?segmentLabel . }
}
GROUP BY ?segmentLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segmentLabel ?avgAllocationPct ?avgReturnPct ?totalHoldingValue WHERE {
  {
    SELECT ?segmentLabel (AVG(xsd:decimal(?allocPct)) AS ?avgAllocationPct) WHERE {
      ?inv a wm:Investor ;
           wm:hasSegment ?seg ;
           wm:hasSectorAllocation ?sa .
      ?seg rdfs:label ?segmentLabel .
      ?sa wm:allocationPct ?allocPct .
    }
    GROUP BY ?segmentLabel
  }
  {
    SELECT ?segmentLabel (AVG(xsd:decimal(?returnsPct)) AS ?avgReturnPct) (SUM(xsd:decimal(?currentValue)) AS ?totalHoldingValue) WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:hasSegment ?seg ;
          wm:returnsPct ?returnsPct ;
          wm:currentValue ?currentValue .
      ?seg rdfs:label ?segmentLabel .
    }
    GROUP BY ?segmentLabel
  }
}
ORDER BY ?segmentLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?id ?totalCashFlow WHERE {
  {
    SELECT ?category ?id ?totalCashFlow WHERE {
      BIND("InvestmentGoal" AS ?category)
      ?ig a wm:InvestmentGoal ;
          wm:goalId ?id ;
          wm:belongsToInvestor ?inv .
      {
        SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
          ?cf a wm:CashFlow ;
              wm:cashFlowOfInvestor ?inv ;
              wm:amount ?amount .
        } GROUP BY ?inv
      }
    }
  }
  UNION
  {
    SELECT ?category ?id ?totalCashFlow WHERE {
      BIND("ScenarioRebalancing" AS ?category)
      ?sr a wm:ScenarioRebalancing ;
          wm:scenario ?id ;
          wm:scenarioRebalancingOfInvestor ?inv .
      {
        SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?totalCashFlow) WHERE {
          ?cf a wm:CashFlow ;
              wm:cashFlowOfInvestor ?inv ;
              wm:amount ?amount .
        } GROUP BY ?inv
      }
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(?netCashFlow) AS ?totalNetCashFlow)
       (AVG(?goalProgress) AS ?avgGoalProgress)
       (SUM(?holdingGain) AS ?totalHoldingGain)
       (AVG(?riskScore) AS ?avgRiskScore)
       (AVG(?allocationPct) AS ?avgAllocationPct)
WHERE {
  ?inv a wm:Investor ;
       wm:category ?category .

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?netCashFlow) WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?prog)) AS ?goalProgress) WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:belongsToInvestor ?inv ;
          wm:progressPct ?prog .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?gain)) AS ?holdingGain) WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:heldByInvestor ?inv ;
          wm:currentValue ?curr ;
          wm:cost ?cost .
      BIND(xsd:decimal(?curr) - xsd:decimal(?cost) AS ?gain)
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?risk)) AS ?riskScore) WHERE {
      ?ph3 a wm:PortfolioHealth ;
           wm:healthOfInvestor ?inv ;
           wm:riskScore ?risk .
    } GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?alloc)) AS ?allocationPct) WHERE {
      ?sa a wm:SectorAllocation ;
          wm:allocationOfInvestor ?inv ;
          wm:allocationPct ?alloc .
    } GROUP BY ?inv
  }
}
GROUP BY ?category
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?holdingId ?categoryLabel ?sectorLabel ?investmentTypeLabel ?segment
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:holdingId ?holdingId ;
           wm:hasCategory ?cat ;
           wm:hasSector ?sec ;
           wm:hasInvestmentType ?invType ;
           wm:hasSegment ?seg .
  FILTER NOT EXISTS { ?holding wm:returnsPct ?ret . }

  OPTIONAL { ?cat rdfs:label ?categoryLabel . }
  OPTIONAL { ?sec rdfs:label ?sectorLabel . }
  OPTIONAL { ?invType rdfs:label ?investmentTypeLabel . }
  BIND (STR(?seg) AS ?segment)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goalLabel (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  ?ig a wm:InvestmentGoal ;
      wm:investmentGoal ?goalLabel ;
      wm:belongsToInvestor ?inv .
  ?inv wm:investorId ?invId .
  ?cf a wm:CashFlow ;
      wm:investorId ?invId ;
      wm:amount ?amount .
}
GROUP BY ?goalLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance (SUM(?depositAmt) AS ?totalDeposit) (SUM(?rebalanceAmt) AS ?totalRebalance) WHERE {
  ?inv wm:riskTolerance ?riskTolerance .

  {
    ?cf a wm:CashFlow ;
        wm:cashFlowOfInvestor ?inv ;
        wm:amount ?amt ;
        wm:type ?cfType .
    FILTER(CONTAINS(LCASE(STR(?cfType)), "deposit"))
    BIND(xsd:decimal(?amt) AS ?depositAmt)
    BIND(xsd:decimal("0") AS ?rebalanceAmt)
  }
  UNION
  {
    ?ra a wm:RebalancingAction ;
        wm:rebalancingActionOfInvestor ?inv ;
        wm:amount ?raAmt .
    BIND(xsd:decimal("0") AS ?depositAmt)
    BIND(xsd:decimal(?raAmt) AS ?rebalanceAmt)
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?holdingGain) AS ?totalHoldingGain)
       (SUM(?rebalanceAmt) AS ?totalRebalancingAmount)
       (SUM(?scenarioChange) AS ?totalScenarioChange)
       (SUM(?cashFlowAmt) AS ?totalCashFlow)
WHERE {
  ?inv a wm:Investor ;
       wm:riskTolerance ?riskTolerance .

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?curr) - xsd:decimal(?cst)) AS ?holdingGain)
    WHERE {
      ?inv wm:hasHolding ?hold .
      ?hold wm:currentValue ?curr ;
            wm:cost ?cst .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?rebalanceAmt)
    WHERE {
      ?inv wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?amt .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?new) - xsd:decimal(?cur)) AS ?scenarioChange)
    WHERE {
      ?inv wm:hasScenarioRebalancing ?sc .
      ?sc wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?cfAmt)) AS ?cashFlowAmt)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmt .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  {
    SELECT DISTINCT ?inv WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:shortfall ?shortfall .
      FILTER(xsd:decimal(?shortfall) > 0)
    }
  }
  {
    SELECT DISTINCT ?inv WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:heldByInvestor ?inv ;
            wm:returnsPct ?ret .
      FILTER(xsd:decimal(?ret) < 0)
    }
  }
  {
    SELECT DISTINCT ?inv WHERE {
      ?alloc a wm:SectorAllocation ;
            wm:allocationOfInvestor ?inv ;
            wm:allocationPct ?allocPct .
      FILTER(xsd:decimal(?allocPct) > 40)
    }
  }
  {
    SELECT DISTINCT ?inv WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:diversificationScore ?divScore .
      FILTER(xsd:decimal(?divScore) < 30)
    }
  }
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?goalCount ?holdingCount ?cashFlowCount ?rebalanceCount ?scenarioCount WHERE {
  {
    SELECT (COUNT(DISTINCT ?g) AS ?goalCount) WHERE {
      ?g wm:goalId ?gid .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?h) AS ?holdingCount) WHERE {
      ?h wm:holdingId ?hid .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?c) AS ?cashFlowCount) WHERE {
      ?c wm:cashFlowId ?cid .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?r) AS ?rebalanceCount) WHERE {
      ?r wm:rebalanceId ?rid .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?s) AS ?scenarioCount) WHERE {
      ?s wm:scenarioRebalanceId ?sid .
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName
WHERE {
  ?inv a wm:Investor ;
       rdfs:label ?investorName ;
       wm:riskTolerance ?riskTol ;
       wm:hasPortfolioHealth ?ph ;
       wm:hasSectorAllocation ?sa .

  FILTER(LCASE(STR(?riskTol)) = "aggressive") .

  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 60) .

  ?sa wm:allocationPct ?allocPct .
  FILTER(xsd:decimal(?allocPct) > 30) .

  FILTER EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold wm:investmentName ?holdName .
    FILTER(LCASE(STR(?holdName)) = "gold")
  }

  FILTER EXISTS {
    ?inv wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER(xsd:decimal(?shortfall) > 0)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?ph a wm:PortfolioHealth ;
      wm:riskScore ?riskScore ;
      wm:liquidityScore ?liqScore ;
      wm:healthOfInvestor ?investor .
  FILTER(xsd:decimal(?riskScore) > 80) .
  FILTER(xsd:decimal(?liqScore) < 20) .
  ?investor a wm:Investor ;
            wm:segment ?segLabel .
  FILTER(LCASE(STR(?segLabel)) = "conservative") .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?totalCashFlow ?avgGoalProgress ?totalHoldingGain ?riskScore ?totalAllocationPct
WHERE {
  {
    SELECT ?investorId (SUM(xsd:decimal(?amt)) AS ?totalCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amt .
    }
    GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId (AVG(xsd:decimal(?prog)) AS ?avgGoalProgress)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:progressPct ?prog .
    }
    GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:currentValue ?cv ;
          wm:cost ?c .
      BIND (xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
    }
    GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId (MAX(xsd:decimal(?rs)) AS ?riskScore)
    WHERE {
      ?phl a wm:PortfolioHealth ;
          wm:investorId ?investorId ;
          wm:riskScore ?rs .
    }
    GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?alloc)) AS ?totalAllocationPct)
    WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?alloc .
    }
    GROUP BY ?investorId
  }
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?score
WHERE {
  {
    SELECT ?inv ( (COALESCE(?cashFlow2025, 0) + COALESCE(?rebalanceAmt, 0) - COALESCE(?shortfallSum, 0) + COALESCE(?allocChange, 0)) AS ?score )
    WHERE {
      OPTIONAL {
        SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?cashFlow2025)
        WHERE {
          ?cf a wm:CashFlow ;
              wm:cashFlowOfInvestor ?inv ;
              wm:amount ?amount ;
              wm:date ?date .
          FILTER regex(?date, "^2025")
        }
        GROUP BY ?inv
      }
      OPTIONAL {
        SELECT ?inv (SUM(xsd:decimal(?raAmount)) AS ?rebalanceAmt)
        WHERE {
          ?ra a wm:RebalancingAction ;
              wm:rebalancingActionOfInvestor ?inv ;
              wm:amount ?raAmount .
        }
        GROUP BY ?inv
      }
      OPTIONAL {
        SELECT ?inv (SUM(xsd:decimal(?shortfall)) AS ?shortfallSum)
        WHERE {
          ?g a wm:InvestmentGoal ;
              wm:belongsToInvestor ?inv ;
              wm:shortfall ?shortfall .
        }
        GROUP BY ?inv
      }
      OPTIONAL {
        SELECT ?inv (SUM(xsd:decimal(?newPct) - xsd:decimal(?curPct)) AS ?allocChange)
        WHERE {
          ?s a wm:ScenarioRebalancing ;
              wm:scenarioRebalancingOfInvestor ?inv ;
              wm:newAllocationPct ?newPct ;
              wm:currentAllocationPct ?curPct .
        }
        GROUP BY ?inv
      }
    }
    ORDER BY DESC(?score)
    LIMIT 10
  }
  ?inv wm:investorName ?investorName .
}
ORDER BY DESC(?score)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cat (COALESCE(?hg, 0) AS ?totalHoldingGain) (COALESCE(?raAmt, 0) AS ?totalRebalancingAmount) (COALESCE(?scChange, 0) AS ?totalScenarioChange) (COALESCE(?cfAmt, 0) AS ?totalCashFlowAmount)
WHERE {
  {
    SELECT ?cat (SUM(?cv - ?cost) AS ?hg) WHERE {
      ?h a wm:PortfolioHolding ;
         wm:hasCategory ?cat ;
         wm:cost ?cost ;
         wm:currentValue ?cv .
    } GROUP BY ?cat
  }
  OPTIONAL {
    SELECT ?cat (SUM(?amt) AS ?raAmt) WHERE {
      ?ra a wm:RebalancingAction ;
          wm:amount ?amt ;
          wm:rebalancingActionOfInvestor ?inv .
      ?inv wm:hasHolding ?h .
      ?h wm:hasCategory ?cat .
    } GROUP BY ?cat
  }
  OPTIONAL {
    SELECT ?cat (SUM(?new - ?cur) AS ?scChange) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur ;
          wm:scenarioRebalancingOfInvestor ?inv .
      ?inv wm:hasHolding ?h .
      ?h wm:hasCategory ?cat .
    } GROUP BY ?cat
  }
  OPTIONAL {
    SELECT ?cat (SUM(?amt) AS ?cfAmt) WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amt ;
          wm:cashFlowOfInvestor ?inv .
      ?inv wm:hasHolding ?h .
      ?h wm:hasCategory ?cat .
    } GROUP BY ?cat
  }
}
ORDER BY ?cat

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?investorName ?totalCash ?avgProgress
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalCash)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amount ;
          wm:cashFlowOfInvestor ?investor .
    }
    GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?progressPct)) AS ?avgProgress)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:progressPct ?progressPct .
      FILTER(?progressPct < 50)
    }
    GROUP BY ?investor
  }
  ?investor wm:investorName ?investorName .
}
ORDER BY DESC(?totalCash)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorName ?investorId ?avgSharpe ?avgVol ?totalHoldingGain ?riskScore
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?inv (AVG(xsd:decimal(?sharpeVal)) AS ?avgSharpe) (AVG(xsd:decimal(?volVal)) AS ?avgVol)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:avgSharpeRatio ?sharpeVal ;
            wm:avgVolatilityPct ?volVal .
    }
    GROUP BY ?inv
    HAVING (AVG(xsd:decimal(?sharpeVal)) < 0 && AVG(xsd:decimal(?volVal)) > 20)
  }

  {
    SELECT ?inv ((SUM(xsd:decimal(?currVal)) - SUM(xsd:decimal(?costVal))) AS ?totalHoldingGain)
    WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:heldByInvestor ?inv ;
            wm:currentValue ?currVal ;
            wm:cost ?costVal .
    }
    GROUP BY ?inv
    HAVING ((SUM(xsd:decimal(?currVal)) - SUM(xsd:decimal(?costVal))) < 0)
  }

  OPTIONAL {
    ?ph a wm:PortfolioHealth ;
         wm:healthOfInvestor ?inv ;
         wm:riskScore ?riskScore .
    FILTER(?riskScore > 50)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?investorName ?investorId
WHERE {
  ?investor wm:hasPortfolioHealth ?ph .
  ?ph wm:diversificationScore ?divScore ;
      wm:liquidityScore ?liqScore .
  FILTER ( xsd:decimal(?divScore) < 30 && xsd:decimal(?liqScore) < 30 )
  OPTIONAL { ?investor wm:investorName ?investorName . }
  OPTIONAL { ?investor wm:investorId ?investorId . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?avgGoalProgressPct ?avgHealthRiskScore ?avgLiquidityScore
WHERE {
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgressPct)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:belongsToInvestor ?inv ;
            wm:progressPct ?progressPct .
      ?inv wm:riskTolerance ?riskTolerance .
    }
    GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?riskScore)) AS ?avgHealthRiskScore)
    WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:healthOfInvestor ?inv ;
          wm:riskScore ?riskScore .
      ?inv wm:riskTolerance ?riskTolerance .
    }
    GROUP BY ?riskTolerance
  }
  {
    SELECT ?riskTolerance (AVG(xsd:decimal(?liquidityScore)) AS ?avgLiquidityScore)
    WHERE {
      ?ph2 a wm:PortfolioHealth ;
            wm:healthOfInvestor ?inv2 ;
            wm:liquidityScore ?liquidityScore .
      ?inv2 wm:riskTolerance ?riskTolerance .
    }
    GROUP BY ?riskTolerance
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month ?triggeredAction (AVG(xsd:decimal(?amount)) AS ?avgAmount)
WHERE {
  {
    SELECT DISTINCT ?inv ?month
    WHERE {
      ?cf a wm:CashFlow ;
          wm:date ?date ;
          wm:cashFlowOfInvestor ?inv .
      BIND(SUBSTR(?date, 1, 7) AS ?month)
    }
  }
  ?ra a wm:RebalancingAction ;
      wm:amount ?amount ;
      wm:hasRebalancingDecision ?decision ;
      wm:rebalancingActionOfInvestor ?inv .
  ?sr a wm:ScenarioRebalancing ;
      wm:hasTriggeredAction ?decision ;
      wm:triggeredAction ?triggeredAction .
}
GROUP BY ?month ?triggeredAction

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?bucket (SUM(?totalCash) AS ?netCashFlow) WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?amount)) AS ?totalCash) WHERE {
      ?cf a wm:CashFlow ;
          wm:amount ?amount ;
          wm:cashFlowOfInvestor ?investor .
    } GROUP BY ?investor
  }
  {
    SELECT ?investor (SAMPLE(?bucket) AS ?bucket) WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:belongsToInvestor ?investor ;
          wm:timeToGoalMonths ?months .
      BIND(
        IF(xsd:decimal(?months) <= 12, "Short",
          IF(xsd:decimal(?months) <= 60, "Medium", "Long")
        ) AS ?bucket)
    } GROUP BY ?investor
  }
}
GROUP BY ?bucket

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?rebalanceId ?action ?month ?monthlyTxCount
WHERE {
  ?ra a wm:RebalancingAction ;
      wm:rebalanceId ?rebalanceId ;
      wm:rebalancingActionOfInvestor ?inv .
  OPTIONAL { ?ra wm:action ?action . }

  {
    SELECT ?inv ?month (COUNT(?cf) AS ?monthlyTxCount)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:date ?date .
      BIND(SUBSTR(?date,1,7) AS ?month)
    }
    GROUP BY ?inv ?month
  }
}
ORDER BY ?rebalanceId ?month

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:timeToGoalMonths ?months ;
            wm:belongsToInvestor ?inv .
      FILTER(xsd:decimal(?months) <= 12)
      ?inv wm:investorId ?investorId .
    }
  }
  {
    SELECT DISTINCT ?investorId
    WHERE {
      ?ra a wm:RebalancingAction ;
          wm:action ?action ;
          wm:rebalancingActionOfInvestor ?inv .
      FILTER(CONTAINS(LCASE(STR(?action)), "de-risking"))
      ?inv wm:investorId ?investorId .
    }
  }
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:hasCashFlow ?cashflow .
  ?cashflow a wm:CashFlow ;
            wm:date ?date .
  FILTER regex(?date, "^2025")
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (SUM(?totalCashFlow) AS ?sumCashFlow)
       (SUM(?totalRebalanceAmount) AS ?sumRebalanceAmount)
       (AVG(?avgAllocChange) AS ?avgAllocChange)
       (AVG(?avgRiskScore) AS ?avgRiskScore)
       (AVG(?avgGoalMatchPct) AS ?avgGoalMatchPct)
WHERE {
  ?inv a wm:Investor ;
       wm:category ?category .

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?totalCashFlow)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?totalRebalanceAmount)
    WHERE {
      ?inv wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?amt .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?allocChange)) AS ?avgAllocChange)
    WHERE {
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?curr .
      BIND(xsd:decimal(?new) - xsd:decimal(?curr) AS ?allocChange)
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScore)
           (AVG(xsd:decimal(?goalMatchPct)) AS ?avgGoalMatchPct)
    WHERE {
      ?inv wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?riskScore ;
          wm:goalMatchPct ?goalMatchPct .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?category
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?score
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  BIND(
    ( COALESCE(
        (SELECT (SUM(xsd:decimal(?cfAmt)) AS ?netCashFlow)
         WHERE {
           ?inv wm:hasCashFlow ?cf .
           ?cf wm:amount ?cfAmt .
         }), xsd:decimal("0"))
      + COALESCE(
        (SELECT (SUM(xsd:decimal(?cv) - xsd:decimal(?c)) AS ?holdingGain)
         WHERE {
           ?inv wm:hasHolding ?h .
           ?h wm:currentValue ?cv .
           ?h wm:cost ?c .
         }), xsd:decimal("0"))
      - COALESCE(
        (SELECT (AVG(xsd:decimal(?sf)) AS ?avgShortfall)
         WHERE {
           ?inv wm:hasInvestmentGoal ?g .
           ?g wm:shortfall ?sf .
         }), xsd:decimal("0"))
      + COALESCE(
        (SELECT (SUM(xsd:decimal(?rebAmt)) AS ?rebalanceAmt)
         WHERE {
           ?inv wm:hasRebalancingAction ?r .
           ?r wm:amount ?rebAmt .
         }), xsd:decimal("0"))
    ) AS ?score)
}
ORDER BY DESC(?score)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
