       wm:investorName ?investorName ;
       wm:hasInvestmentGoal ?goal .

  ?goal wm:investmentGoal ?goalTypeLiteral ;
        wm:shortfall ?shortfall .

  FILTER(CONTAINS(LCASE(STR(?goalTypeLiteral)), "growth"))
  FILTER(xsd:decimal(?shortfall) > 0)

  FILTER EXISTS {
    ?inv wm:hasHolding ?holding .
    ?holding wm:hasSector ?sector .
    ?sector rdfs:label ?sectorLabel .
    FILTER(CONTAINS(LCASE(STR(?sectorLabel)), "technology"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category (COALESCE(?invCount, 0) AS ?profileCount) (COALESCE(?holdCount, 0) AS ?holdingCount)
WHERE {
  {
    SELECT DISTINCT ?category
    WHERE {
      { ?inv a wm:Investor ; wm:category ?category . }
      UNION
      { ?hold a wm:PortfolioHolding ; wm:category ?category . }
    }
  }
  OPTIONAL {
    SELECT ?category (COUNT(?inv) AS ?invCount)
    WHERE {
      ?inv a wm:Investor ; wm:category ?category .
    }
    GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (COUNT(?hold) AS ?holdCount)
    WHERE {
      ?hold a wm:PortfolioHolding ; wm:category ?category .
    }
    GROUP BY ?category
  }
}
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol ?cfType (AVG(?avgProgress) AS ?avgProgressPct)
WHERE {
  {
    SELECT ?investor ?avgProgress WHERE {
      SELECT ?investor (AVG(xsd:decimal(?progress)) AS ?avgProgress) WHERE {
        ?goal a wm:InvestmentGoal ;
              wm:belongsToInvestor ?investor ;
              wm:progressPct ?progress .
      } GROUP BY ?investor
    }
  }
  {
    SELECT DISTINCT ?investor ?riskTol ?cfType WHERE {
      ?investor a wm:Investor .
      OPTIONAL { ?investor wm:riskTolerance ?riskTol . }
      ?investor wm:hasCashFlow ?cf .
      ?cf wm:type ?cfType .
    }
  }
}
GROUP BY ?riskTol ?cfType

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName
WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?sa .
    ?sa wm:allocationPct ?allocPct .
    FILTER(xsd:decimal(?allocPct) > 20)
  }

  FILTER EXISTS {
    ?inv wm:hasRebalancingAction ?ra .
    ?ra wm:action ?action .
    FILTER(CONTAINS(LCASE(STR(?action)), "rebalance sell"))
  }

  FILTER EXISTS {
    ?inv wm:hasScenarioRebalancing ?sr .
    ?sr wm:scenario ?scenarioLabel .
    FILTER(CONTAINS(LCASE(STR(?scenarioLabel)), "bear"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName (SUM(xsd:decimal(?gain)) AS ?totalGain)
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:cost ?cost ;
           wm:currentValue ?currentValue .
  BIND (xsd:decimal(?currentValue) - xsd:decimal(?cost) AS ?gain) .
  ?investor wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }
}
GROUP BY ?investorId ?investorName
ORDER BY DESC(?totalGain)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?ra) AS ?rebalanceCount)
       (COUNT(DISTINCT ?ig) AS ?goalCount)
       (COUNT(DISTINCT ?sa) AS ?allocationCount)
       (AVG(xsd:decimal(?rs)) AS ?avgRiskScore)
WHERE {
  OPTIONAL { ?ra a wm:RebalancingAction . }
  OPTIONAL { ?ig a wm:InvestmentGoal . }
  OPTIONAL { ?sa a wm:SectorAllocation . }
  OPTIONAL {
    ?ph a wm:PortfolioHealth ;
        wm:riskScore ?rs .
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?depositTotal ?withdrawalTotal ?liquidityScore WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  {
    SELECT ?inv (SUM(?depositAmt) AS ?depositTotal) (SUM(?withdrawAmt) AS ?withdrawalTotal) WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt ;
          wm:type ?type .
      BIND (IF(LCASE(?type) = "deposit", xsd:decimal(?amt), 0) AS ?depositAmt)
      BIND (IF(LCASE(?type) = "withdrawal", xsd:decimal(?amt), 0) AS ?withdrawAmt)
    } GROUP BY ?inv
  }

  ?ph a wm:PortfolioHealth ;
       wm:healthOfInvestor ?inv ;
       wm:liquidityScore ?liquidityScore .
  FILTER(xsd:decimal(?liquidityScore) < 30)
  FILTER(?depositTotal < ?withdrawalTotal)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasInvestmentGoal ?goal ;
       wm:hasPortfolioHealth ?ph .

  ?goal wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0) .

  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 65) .

  FILTER EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold wm:returnsPct ?returnsPct .
    FILTER(xsd:decimal(?returnsPct) < 0)
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?totalCash)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    }
    GROUP BY ?inv
    HAVING (SUM(xsd:decimal(?amount)) < 10000)
  }
}
ORDER BY ?investorId

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?timeHorizon ?year ?totalCashFlow ?avgScenarioChange ?avgAllocationPct ?totalSectorInvestment ?sector ?sectorHoldingValue
WHERE {
  {
    SELECT ?investorId ?year (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:date ?date ;
          wm:amount ?amount .
      BIND (SUBSTR(?date,1,4) AS ?year)
    }
    GROUP BY ?investorId ?year
  }
  OPTIONAL {
    ?inv a wm:Investor ;
         wm:investorId ?investorId ;
         wm:timeHorizon ?timeHorizon .
  }
  OPTIONAL {
    {
      SELECT ?investorId (AVG(xsd:decimal(?allocDiff)) AS ?avgScenarioChange)
      WHERE {
        ?sr a wm:ScenarioRebalancing ;
            wm:investorId ?investorId ;
            wm:currentAllocationPct ?curr ;
            wm:newAllocationPct ?new .
        BIND (xsd:decimal(?new) - xsd:decimal(?curr) AS ?allocDiff)
      }
      GROUP BY ?investorId
    }
  }
  OPTIONAL {
    {
      SELECT ?investorId (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct) (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
      WHERE {
        ?sa a wm:SectorAllocation ;
            wm:investorId ?investorId ;
            wm:allocationPct ?allocationPct ;
            wm:totalInvestment ?totalInvestment .
      }
      GROUP BY ?investorId
    }
  }
  OPTIONAL {
    {
      SELECT ?investorId ?sector (SUM(xsd:decimal(?currentValue)) AS ?sectorHoldingValue)
      WHERE {
        ?ph a wm:PortfolioHolding ;
            wm:investorId ?investorId ;
            wm:sector ?sector ;
            wm:currentValue ?currentValue .
      }
      GROUP BY ?investorId ?sector
    }
  }
}
ORDER BY ?investorId ?year ?sector

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  FILTER (
    EXISTS {
      ?investor wm:segment ?segLiteral .
      FILTER(CONTAINS(LCASE(STR(?segLiteral)), "long-term"))
    } ||
    EXISTS {
      ?investor wm:timeHorizon ?thLiteral .
      FILTER(CONTAINS(LCASE(STR(?thLiteral)), "long-term"))
    }
  )

  FILTER EXISTS {
    ?investor wm:hasInvestmentGoal ?goal .
    ?goal wm:investmentGoal ?goalLabel .
    FILTER(LCASE(STR(?goalLabel)) = "retirement planning")
  }

  FILTER EXISTS {
    ?investor wm:hasHolding ?holding .
    ?holding wm:sector ?sectorLiteral .
    FILTER(LCASE(STR(?sectorLiteral)) = "healthcare")
  }

  FILTER EXISTS {
    ?investor wm:hasPortfolioHealth ?ph .
    ?ph wm:diversificationScore ?divScore .
    FILTER(xsd:decimal(?divScore) < 50)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?categoryLabel ?totalCashFlow ?totalScenarioChange ?avgAllocationPct ?totalSectorInvestment WHERE {
  {
    SELECT ?categoryLabel (SUM(xsd:decimal(?amt)) AS ?totalCashFlow) WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat .
      ?cat rdfs:label ?categoryLabel .
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
    }
    GROUP BY ?categoryLabel
  }
  {
    SELECT ?categoryLabel (SUM(xsd:decimal(?new) - xsd:decimal(?cur)) AS ?totalScenarioChange) WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat .
      ?cat rdfs:label ?categoryLabel .
      ?sr a wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?inv ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
    }
    GROUP BY ?categoryLabel
  }
  {
    SELECT ?categoryLabel (AVG(xsd:decimal(?allocPct)) AS ?avgAllocationPct) (SUM(xsd:decimal(?totalInv)) AS ?totalSectorInvestment) WHERE {
      ?inv a wm:Investor ;
           wm:hasCategory ?cat .
      ?cat rdfs:label ?categoryLabel .
      ?sa a wm:SectorAllocation ;
          wm:allocationOfInvestor ?inv ;
          wm:allocationPct ?allocPct ;
          wm:totalInvestment ?totalInv .
    }
    GROUP BY ?categoryLabel
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?rebalanceId ?logicString ?action ?logicEntity
WHERE {
  ?ra rdf:type wm:RebalancingAction ;
      wm:rebalanceId ?rebalanceId .
  FILTER(CONTAINS(LCASE(STR(?rebalanceId)), "0000aba5-8fe8-4dcf-b422-fd78608ffddb"))
  OPTIONAL { ?ra wm:logic ?logicString . }
  OPTIONAL { ?ra wm:action ?action . }
  OPTIONAL { ?ra wm:hasRebalancingLogic ?logicEntity . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?holdingGain ?allocationConcentration ?rebalancingGap ?scenarioChange ?goalVolatility WHERE {
  {
    SELECT ?category (AVG(xsd:decimal(?returnsPct)) AS ?holdingGain) WHERE {
      ?inv wm:category ?category .
      ?inv wm:hasHolding ?holding .
      ?holding wm:returnsPct ?returnsPct .
    } GROUP BY ?category
  }
  {
    SELECT ?category (AVG(xsd:decimal(?allocationPct)) AS ?allocationConcentration) WHERE {
      ?inv wm:category ?category .
      ?inv wm:hasSectorAllocation ?alloc .
      ?alloc wm:allocationPct ?allocationPct .
    } GROUP BY ?category
  }
  {
    SELECT ?category (AVG(xsd:decimal(?targetAllocationPct) - xsd:decimal(?currentAllocationPct)) AS ?rebalancingGap) WHERE {
      ?inv wm:category ?category .
      ?inv wm:hasRebalancingAction ?rebAct .
      ?rebAct wm:targetAllocationPct ?targetAllocationPct .
      ?rebAct wm:currentAllocationPct ?currentAllocationPct .
    } GROUP BY ?category
  }
  {
    SELECT ?category (AVG(xsd:decimal(?newAllocationPct) - xsd:decimal(?currentAllocationPctScenario)) AS ?scenarioChange) WHERE {
      ?inv wm:category ?category .
      ?inv wm:hasScenarioRebalancing ?scenario .
      ?scenario wm:newAllocationPct ?newAllocationPct .
      ?scenario wm:currentAllocationPct ?currentAllocationPctScenario .
    } GROUP BY ?category
  }
  {
    SELECT ?category (AVG(xsd:decimal(?avgVolatilityPct)) AS ?goalVolatility) WHERE {
      ?inv wm:category ?category .
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:avgVolatilityPct ?avgVolatilityPct .
    } GROUP BY ?category
  }
}
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  ?inv wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScore .
  FILTER(?riskScore > 70)

  {
    SELECT DISTINCT ?inv
    WHERE {
      ?inv wm:hasSectorAllocation ?alloc .
      ?alloc wm:allocationPct ?allocPct .
      FILTER(?allocPct > 30)
    }
  }

  {
    SELECT DISTINCT ?inv
    WHERE {
      ?inv wm:hasHolding ?hold .
      ?hold wm:returnsPct ?retPct .
      FILTER(?retPct < 0)
    }
  }

  {
    SELECT ?inv
    WHERE {
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?prog .
    }
    GROUP BY ?inv
    HAVING (AVG(?prog) < 30)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorName ?investorId
WHERE {
  ?investor a wm:Investor ;
            wm:investorName ?investorName ;
            wm:investorId ?investorId ;
            wm:hasScenarioRebalancing ?sr .
  ?sr wm:hasMarketScenario ?ms .
  ?ms wm:logic ?logic ;
      rdfs:label ?label .
  FILTER(CONTAINS(LCASE(STR(?logic)), "manual override"))
  FILTER(CONTAINS(LCASE(STR(?label)), "bear"))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?divScore
WHERE {
  ?investor rdf:type wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:hasPortfolioHealth ?ph ;
            wm:hasSectorAllocation ?alloc .
  ?ph wm:diversificationScore ?divScore .
  ?alloc wm:allocationPct ?allocPct .
  FILTER (xsd:decimal(?allocPct) > 30)
}
ORDER BY xsd:decimal(?divScore)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?avgProgress ?avgRiskScore ?avgHoldingReturn
WHERE {
  # distinct categories present in the data
  {
    SELECT DISTINCT ?category WHERE {
      ?inv a wm:Investor .
      ?inv wm:category ?category .
    }
  }

  OPTIONAL {
    SELECT ?category (AVG(xsd:decimal(?p)) AS ?avgProgress) WHERE {
      ?inv a wm:Investor .
      ?inv wm:category ?category .
      ?ig a wm:InvestmentGoal .
      ?ig wm:belongsToInvestor ?inv .
      ?ig wm:progressPct ?p .
    } GROUP BY ?category
  }

  OPTIONAL {
    SELECT ?category (AVG(xsd:decimal(?r)) AS ?avgRiskScore) WHERE {
      ?inv a wm:Investor .
      ?inv wm:category ?category .
      ?inv wm:hasPortfolioHealth ?ph .
      ?ph wm:riskScore ?r .
    } GROUP BY ?category
  }

  OPTIONAL {
    SELECT ?category (AVG(xsd:decimal(?ret)) AS ?avgHoldingReturn) WHERE {
      ?inv a wm:Investor .
      ?inv wm:category ?category .
      ?phld a wm:PortfolioHolding .
      ?phld wm:heldByInvestor ?inv .
      ?phld wm:returnsPct ?ret .
    } GROUP BY ?category
  }
}
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon ?avgAllocChange ?avgProgress ?avgVolatility WHERE {
  {
    SELECT ?timeHorizon (AVG(?allocChange) AS ?avgAllocChange) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?inv ;
          wm:currentAllocationPct ?curr ;
          wm:newAllocationPct ?new .
      ?inv wm:timeHorizon ?timeHorizon .
      BIND(?new - ?curr AS ?allocChange)
    }
    GROUP BY ?timeHorizon
  }
  {
    SELECT ?timeHorizon (AVG(?progress) AS ?avgProgress) (AVG(?vol) AS ?avgVolatility) WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:belongsToInvestor ?inv ;
          wm:progressPct ?progress ;
          wm:avgVolatilityPct ?vol .
      ?inv wm:timeHorizon ?timeHorizon .
    }
    GROUP BY ?timeHorizon
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holding ?holdingId
WHERE {
  ?holding a wm:PortfolioHolding .
  OPTIONAL { ?holding wm:holdingId ?holdingId . }
  FILTER NOT EXISTS { ?holding wm:hasCategory ?cat . }
  FILTER NOT EXISTS { ?holding wm:category ?catLit . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month ?scenario (AVG(?invGoalAvg) AS ?avgProgressPct) (AVG(?invRebAvg) AS ?avgRebalanceAmt)
WHERE {
  {
    SELECT DISTINCT ?invId ?month WHERE {
      ?cf a wm:CashFlow ;
          wm:date ?date ;
          wm:investorId ?invId .
      BIND(SUBSTR(STR(?date),1,7) AS ?month)
    }
  }
  {
    SELECT DISTINCT ?invId ?scenario WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:scenario ?scenario ;
          wm:investorId ?invId .
    }
  }
  OPTIONAL {
    SELECT ?invId (AVG(xsd:decimal(?progressPct)) AS ?invGoalAvg) WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:progressPct ?progressPct ;
          wm:investorId ?invId .
    } GROUP BY ?invId
  }
  OPTIONAL {
    SELECT ?invId (AVG(xsd:decimal(?amount)) AS ?invRebAvg) WHERE {
      ?ra a wm:RebalancingAction ;
          wm:amount ?amount ;
          wm:investorId ?invId .
    } GROUP BY ?invId
  }
}
GROUP BY ?month ?scenario

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?riskPressureScore ?avgProgressPct
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  ?inv wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScore ;
      wm:liquidityScore ?liqScore ;
      wm:diversificationScore ?divScore .

  BIND( ( xsd:decimal(?riskScore)
          + ( "100"^^xsd:decimal - xsd:decimal(?liqScore) )
          + ( "100"^^xsd:decimal - xsd:decimal(?divScore) )
        ) AS ?riskPressureScore )

  {
    SELECT ?investorId (AVG(xsd:decimal(?progressPct)) AS ?avgProgressPct)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?investorId ;
            wm:progressPct ?progressPct .
    }
    GROUP BY ?investorId
  }

  FILTER(?riskPressureScore > 220)
  FILTER(?avgProgressPct < 40)
}
ORDER BY DESC(?riskPressureScore)

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investor ?investorId ?investorName
WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:investorId ?investorId . }
  OPTIONAL { ?investor wm:investorName ?investorName . }
  OPTIONAL { ?investor wm:riskTolerance ?rtLiteral . }
  OPTIONAL { ?investor wm:hasRiskTolerance ?rtObj . }
  OPTIONAL { ?investor wm:category ?catLiteral . }
  OPTIONAL { ?investor wm:hasCategory ?catObj . }
  FILTER (
    !BOUND(?rtLiteral) && !BOUND(?rtObj) &&
    !BOUND(?catLiteral) && !BOUND(?catObj)
  )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT
  (AVG(xsd:decimal(?allocationPct)) AS ?avgAllocationPct)
  (AVG(xsd:decimal(?returnsPct)) AS ?avgHoldingReturnPct)
  (AVG(xsd:decimal(?volatilityPct)) AS ?avgGoalVolatilityPct)
  (AVG(xsd:decimal(?divScore)) AS ?avgDiversificationScore)
WHERE {
  {
    SELECT ?allocationPct WHERE {
      ?alloc a wm:SectorAllocation ;
            wm:allocationPct ?allocationPct .
    }
  }
  UNION
  {
    SELECT ?returnsPct WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:returnsPct ?returnsPct .
    }
  }
  UNION
  {
    SELECT ?volatilityPct WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:avgVolatilityPct ?volatilityPct .
    }
  }
  UNION
  {
    SELECT ?divScore WHERE {
      ?ph a wm:PortfolioHealth ;
          wm:diversificationScore ?divScore .
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalWithdrawal ?totalDeposit ?liqScore WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?inv (SUM(IF(LCASE(?cfType) = "withdrawal", xsd:decimal(?amt), 0)) AS ?totalWithdrawal)
                (SUM(IF(LCASE(?cfType) = "deposit", xsd:decimal(?amt), 0)) AS ?totalDeposit) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:type ?cfType .
      ?cf wm:allowedValue ?amt .
    } GROUP BY ?inv
    HAVING (SUM(IF(LCASE(?cfType) = "withdrawal", xsd:decimal(?amt), 0)) > SUM(IF(LCASE(?cfType) = "deposit", xsd:decimal(?amt), 0)))
  }

  ?inv wm:hasPortfolioHealth ?ph .
  ?ph wm:liquidityScore ?liqScore .
  FILTER(xsd:decimal(?liqScore) < 30)

  FILTER EXISTS {
    ?hold a wm:PortfolioHolding ;
          wm:heldByInvestor ?inv ;
          wm:returnsPct ?ret .
    FILTER(xsd:decimal(?ret) < 0)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?netCashFlow
WHERE {
  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amount .
    }
    GROUP BY ?inv
  }
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }
}
ORDER BY DESC(?netCashFlow)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?avgProg ?riskScore ?totalAlloc ?action
WHERE {
  # Basic investor identifiers
  ?inv wm:investorId ?investorId ;
       wm:investorName ?investorName .

  # Risk score (any direction)
  {
    SELECT ?inv (MAX(xsd:decimal(?rs)) AS ?riskScore)
    WHERE {
      { ?inv wm:hasPortfolioHealth ?ph . ?ph wm:riskScore ?rs . }
      UNION
      { ?ph wm:healthOfInvestor ?inv . ?ph wm:riskScore ?rs . }
    }
    GROUP BY ?inv
  }
  FILTER(xsd:decimal(?riskScore) > 75)

  # Rebalancing action of type "Rebalance Sell"
  {
    SELECT ?inv (SAMPLE(?act) AS ?action)
    WHERE {
      { ?inv wm:hasRebalancingAction ?ra . ?ra wm:action ?act . }
      UNION
      { ?ra wm:rebalancingActionOfInvestor ?inv . ?ra wm:action ?act . }
    }
    GROUP BY ?inv
  }
  FILTER(LCASE(STR(?action)) = "rebalance sell")

  # Average goal progress per investor
  {
    SELECT ?inv (AVG(xsd:decimal(?prog)) AS ?avgProg)
    WHERE {
      { ?inv wm:hasInvestmentGoal ?goal . ?goal wm:progressPct ?prog . }
      UNION
      { ?goal wm:belongsToInvestor ?inv . ?goal wm:progressPct ?prog . }
    }
    GROUP BY ?inv
  }
  FILTER(xsd:decimal(?avgProg) < 20)

  # Total sector allocation per investor
  {
    SELECT ?inv (SUM(xsd:decimal(?alloc)) AS ?totalAlloc)
    WHERE {
      { ?inv wm:hasSectorAllocation ?allocRec . ?allocRec wm:allocationPct ?alloc . }
      UNION
      { ?allocRec wm:allocationOfInvestor ?inv . ?allocRec wm:allocationPct ?alloc . }
    }
    GROUP BY ?inv
  }
  FILTER(xsd:decimal(?totalAlloc) > 100)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?inv ?invName (SUM(?component) AS ?totalScore) WHERE {
  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorName ?invName . }

  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?component) WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
    } GROUP BY ?inv
  }
  UNION
  {
    SELECT ?inv (SUM(xsd:decimal(?curr) - xsd:decimal(?cost)) AS ?component) WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:heldByInvestor ?inv ;
          wm:currentValue ?curr ;
          wm:cost ?cost .
    } GROUP BY ?inv
  }
  UNION
  {
    SELECT ?inv (SUM(xsd:decimal(?raAmt)) AS ?component) WHERE {
      ?ra a wm:RebalancingAction ;
          wm:rebalancingActionOfInvestor ?inv ;
          wm:amount ?raAmt .
    } GROUP BY ?inv
  }
  UNION
  {
    SELECT ?inv (SUM(xsd:decimal(?new) - xsd:decimal(?cur)) AS ?component) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:scenarioRebalancingOfInvestor ?inv ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
    } GROUP BY ?inv
  }
  UNION
  {
    SELECT ?inv (SUM((-1) * xsd:decimal(?short)) AS ?component) WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:belongsToInvestor ?inv ;
          wm:shortfall ?short .
    } GROUP BY ?inv
  }
}
GROUP BY ?inv ?invName
ORDER BY DESC(?totalScore)
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?field (COUNT(?holding) AS ?missingCount) WHERE {
  {
    ?holding a wm:PortfolioHolding .
    FILTER NOT EXISTS { ?holding wm:investmentType ?inv . }
    FILTER NOT EXISTS { ?holding wm:hasInvestmentType ?invObj . }
    BIND("investment_type" AS ?field)
  }
  UNION
  {
    ?holding a wm:PortfolioHolding .
    FILTER NOT EXISTS { ?holding wm:sector ?sec . }
    FILTER NOT EXISTS { ?holding wm:hasSector ?secObj . }
    BIND("sector" AS ?field)
  }
  UNION
  {
    ?holding a wm:PortfolioHolding .
    FILTER NOT EXISTS { ?holding wm:segment ?seg . }
    FILTER NOT EXISTS { ?holding wm:hasSegment ?segObj . }
    BIND("segment" AS ?field)
  }
  UNION
  {
    ?holding a wm:PortfolioHolding .
    FILTER NOT EXISTS { ?holding wm:category ?cat . }
    FILTER NOT EXISTS { ?holding wm:hasCategory ?catObj . }
    BIND("category" AS ?field)
  }
}
GROUP BY ?field

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance
       (SUM(?holdCnt) AS ?holdingCount)
       (SUM(?goalCnt) AS ?goalCount)
       (SUM(?scenarioCnt) AS ?scenarioCount)
       (SUM(?transactionCnt) AS ?transactionCount)
WHERE {
  {
    SELECT ?inv ?riskTolerance
           (COUNT(DISTINCT ?hold) AS ?holdCnt)
           (COUNT(DISTINCT ?goal) AS ?goalCnt)
           (COUNT(DISTINCT ?scen) AS ?scenarioCnt)
           (COUNT(DISTINCT ?cf) AS ?transactionCnt)
    WHERE {
      ?inv a wm:Investor ;
           wm:hasRiskTolerance ?riskTolerance .
      OPTIONAL { ?inv wm:hasHolding ?hold . }
      OPTIONAL { ?goal a wm:InvestmentGoal ;
                     wm:belongsToInvestor ?inv . }
      OPTIONAL { ?scen a wm:ScenarioRebalancing ;
                     wm:scenarioRebalancingOfInvestor ?inv . }
      OPTIONAL { ?inv wm:hasCashFlow ?cf . }
    }
    GROUP BY ?inv ?riskTolerance
  }
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?holding ?holdingId
WHERE {
  ?holding wm:holdingId ?holdingId .

  FILTER NOT EXISTS { ?holding wm:investmentType ?invLit . }
  FILTER NOT EXISTS { ?holding wm:hasInvestmentType ?invObj . }

  FILTER NOT EXISTS { ?holding wm:sector ?secLit . }
  FILTER NOT EXISTS { ?holding wm:hasSector ?secObj . }

  FILTER NOT EXISTS { ?holding wm:segment ?segLit . }
  FILTER NOT EXISTS { ?holding wm:hasSegment ?segObj . }

  FILTER NOT EXISTS { ?holding wm:category ?catLit . }
  FILTER NOT EXISTS { ?holding wm:hasCategory ?catObj . }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?totalSectorInvestment ?totalCashFlow ?avgGoalProgressPct ?avgScenarioChangePct ?totalRebalancingAmount
WHERE {
  {
    SELECT ?category (SUM(xsd:decimal(?totalInvestment)) AS ?totalSectorInvestment)
    WHERE {
      ?inv a wm:Investor ;
           wm:category ?category ;
           wm:hasSectorAllocation ?sa .
      ?sa wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
    WHERE {
      ?inv a wm:Investor ;
           wm:category ?category ;
           wm:hasCashFlow ?cf .
      ?cf wm:amount ?cfAmount .
    }
    GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgressPct)
    WHERE {
      ?inv a wm:Investor ;
           wm:category ?category ;
           wm:hasInvestmentGoal ?ig .
      ?ig wm:progressPct ?progressPct .
    }
    GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (AVG(xsd:decimal(?delta)) AS ?avgScenarioChangePct)
    WHERE {
      ?inv a wm:Investor ;
           wm:category ?category ;
           wm:hasScenarioRebalancing ?sr .
      ?sr wm:newAllocationPct ?newAlloc ;
          wm:currentAllocationPct ?currAlloc .
      BIND (xsd:decimal(?newAlloc) - xsd:decimal(?currAlloc) AS ?delta)
    }
    GROUP BY ?category
  }
  OPTIONAL {
    SELECT ?category (SUM(xsd:decimal(?raAmount)) AS ?totalRebalancingAmount)
    WHERE {
      ?inv a wm:Investor ;
           wm:category ?category ;
           wm:hasRebalancingAction ?ra .
      ?ra wm:amount ?raAmount .
    }
    GROUP BY ?category
  }
}
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?avgScenarioChange ?avgGoalProgress ?avgVolatility
WHERE {
  {
    SELECT ?category (AVG(xsd:decimal(?change)) AS ?avgScenarioChange)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:category ?category .
      ?inv wm:hasScenarioRebalancing ?sr .
      ?sr wm:currentAllocationPct ?curr .
      ?sr wm:newAllocationPct ?new .
      BIND ((xsd:decimal(?new) - xsd:decimal(?curr)) AS ?change)
    }
    GROUP BY ?category
  }
  {
    SELECT ?category (AVG(xsd:decimal(?progressPct)) AS ?avgGoalProgress) (AVG(xsd:decimal(?volatilityPct)) AS ?avgVolatility)
    WHERE {
      ?inv a wm:Investor .
      ?inv wm:category ?category .
      ?inv wm:hasInvestmentGoal ?goal .
      ?goal wm:progressPct ?progressPct .
      ?goal wm:avgVolatilityPct ?volatilityPct .
    }
    GROUP BY ?category
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?totalHoldingValue ?totalSectorAllocation ?totalCashFlowAmount
WHERE {
  {
    SELECT ?category (SUM(?holdingValue) AS ?totalHoldingValue)
    WHERE {
      ?inv a wm:Investor ;
           wm:category ?category ;
           wm:hasHolding ?holding .
      ?holding wm:currentValue ?holdingValue .
    }
    GROUP BY ?category
  }
  {
    SELECT ?category (SUM(?allocationValue) AS ?totalSectorAllocation)
    WHERE {
      ?inv a wm:Investor ;
           wm:category ?category ;
           wm:hasSectorAllocation ?alloc .
      ?alloc wm:totalInvestment ?allocationValue .
    }
    GROUP BY ?category
  }
  {
    SELECT ?category (SUM(?cashAmount) AS ?totalCashFlowAmount)
    WHERE {
      ?inv a wm:Investor ;
           wm:category ?category ;
           wm:hasCashFlow ?cf .
      ?cf wm:amount ?cashAmount .
    }
    GROUP BY ?category
  }
}
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTolerance ?goalName (COUNT(DISTINCT ?investor) AS ?investorCount)
WHERE {
  ?investor a wm:Investor .
  ?investor wm:hasRiskTolerance ?riskTolerance .
  ?investor wm:hasInvestmentGoal ?goal .
  ?goal wm:investmentGoal ?goalName .

  {
    SELECT DISTINCT ?investor WHERE {
      ?investor wm:hasHolding ?holding .
    }
  }
  {
    SELECT DISTINCT ?investor WHERE {
      ?investor wm:hasSectorAllocation ?allocation .
    }
  }
  {
    SELECT DISTINCT ?investor WHERE {
      ?investor wm:hasCashFlow ?cashFlow .
    }
  }
}
GROUP BY ?riskTolerance ?goalName

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
