PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?logic ?scenario (AVG(xsd:decimal(?allocChange)) AS ?avgAllocChange) (AVG(xsd:decimal(?targetAlloc)) AS ?avgTargetAlloc)
WHERE {
  ?sr a wm:ScenarioRebalancing ;
      wm:scenario ?scenario ;
      wm:currentAllocationPct ?curr ;
      wm:newAllocationPct ?new ;
      wm:hasTriggeredAction ?dec .
  BIND (xsd:decimal(?new) - xsd:decimal(?curr) AS ?allocChange)

  ?ra a wm:RebalancingAction ;
      wm:logic ?logic ;
      wm:targetAllocationPct ?targetAlloc ;
      wm:hasRebalancingDecision ?dec .
}
GROUP BY ?logic ?scenario

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category
       (AVG(?invAvgReturnsPct) AS ?avgReturnsPctByCategory)
       (AVG(?invAvgSharpeRatio) AS ?avgSharpeRatioByCategory)
       (AVG(xsd:decimal(?riskScore)) AS ?avgRiskScoreByCategory)
WHERE {
  ?investor a wm:Investor ;
            wm:category ?category .

  {
    SELECT ?investor (AVG(xsd:decimal(?returnsPct)) AS ?invAvgReturnsPct)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:returnsPct ?returnsPct .
    }
    GROUP BY ?investor
  }

  {
    SELECT ?investor (AVG(xsd:decimal(?sharpe)) AS ?invAvgSharpeRatio)
    WHERE {
      ?investor wm:hasInvestmentGoal ?goal .
      ?goal wm:avgSharpeRatio ?sharpe .
    }
    GROUP BY ?investor
  }

  OPTIONAL {
    ?investor wm:hasPortfolioHealth ?health .
    ?health wm:riskScore ?riskScore .
  }
}
GROUP BY ?category
ORDER BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?cat ?holdingCount ?transactionCount ?goalCount ?scenarioCount WHERE {
  {
    SELECT ?cat (COUNT(?h) AS ?holdingCount) WHERE {
      ?h a wm:PortfolioHolding ;
         wm:hasCategory ?cat .
    } GROUP BY ?cat
  }
  {
    SELECT (COUNT(?cf) AS ?transactionCount) WHERE {
      ?cf a wm:CashFlow .
    }
  }
  {
    SELECT (COUNT(?g) AS ?goalCount) WHERE {
      ?g a wm:InvestmentGoal .
    }
  }
  {
    SELECT (COUNT(?s) AS ?scenarioCount) WHERE {
      ?s a wm:MarketScenario .
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?timeHorizonValue WHERE {
  {
    ?inv a wm:Investor .
    ?inv wm:hasTimeHorizon ?th .
    BIND(STR(?th) AS ?timeHorizonValue)
  } UNION {
    ?inv a wm:Investor .
    ?inv wm:timeHorizon ?thLit .
    BIND(?thLit AS ?timeHorizonValue)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalHoldingGain ?netCashFlow ?riskPressureScore WHERE {
  ?inv wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  {
    SELECT ?inv (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain) WHERE {
      ?inv wm:hasHolding ?hold .
      ?hold wm:cost ?cost .
      ?hold wm:currentValue ?cur .
      BIND(xsd:decimal(?cur) - xsd:decimal(?cost) AS ?gain)
    } GROUP BY ?inv
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?netCashFlow) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    } GROUP BY ?inv
  }

  {
    SELECT ?inv (xsd:decimal(?riskScore) + (100 - xsd:decimal(?liquidityScore)) + (100 - xsd:decimal(?diversificationScore)) AS ?riskPressureScore) WHERE {
      ?ph wm:healthOfInvestor ?inv ;
          wm:riskScore ?riskScore ;
          wm:liquidityScore ?liquidityScore ;
          wm:diversificationScore ?diversificationScore .
    } GROUP BY ?inv
  }

  FILTER(?totalHoldingGain < 0 && ?netCashFlow < 0 && ?riskPressureScore > 180)
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  FILTER EXISTS {
    ?inv wm:hasPortfolioHealth ?ph .
    ?ph wm:riskScore ?riskScore .
    FILTER (xsd:decimal(?riskScore) > 100)
  }

  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?sa .
    ?sa wm:allocationPct ?allocPct .
    FILTER (xsd:decimal(?allocPct) > 100)
  }

  FILTER EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold wm:returnsPct ?retPct .
    FILTER (xsd:decimal(?retPct) < 0)
  }

  FILTER EXISTS {
    ?inv wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER (xsd:decimal(?shortfall) > 0)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?portfolioHealthId ?riskScore ?diversificationScore
WHERE {
  ?ph a wm:PortfolioHealth ;
      wm:portfolioHealthId ?portfolioHealthId ;
      wm:riskScore ?riskScore ;
      wm:diversificationScore ?diversificationScore .
  FILTER ( xsd:decimal(?riskScore) > 80 && xsd:decimal(?diversificationScore) < 20 )
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investor ?investorName
WHERE {
  ?investor a wm:Investor .
  OPTIONAL { ?investor wm:investorName ?investorName . }

  ?investor wm:hasRebalancingAction ?ra .
  OPTIONAL { ?ra wm:logic ?raLogic . }
  OPTIONAL { ?ra rdfs:label ?raLabel . }
  OPTIONAL { ?ra wm:allowedValue ?raAllowed . }
  FILTER(
    (BOUND(?raLogic) && CONTAINS(LCASE(STR(?raLogic)), "manual override")) ||
    (BOUND(?raLabel) && CONTAINS(LCASE(STR(?raLabel)), "manual override")) ||
    (BOUND(?raAllowed) && CONTAINS(LCASE(STR(?raAllowed)), "manual override"))
  )

  ?investor wm:hasScenarioRebalancing ?sr .
  OPTIONAL { ?sr wm:scenario ?srScenario . }
  FILTER(BOUND(?srScenario) && CONTAINS(LCASE(STR(?srScenario)), "flash crash"))
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizonLabel (SUM(?gain) AS ?totalGain) (AVG(?riskScore) AS ?avgRiskScore) (AVG(?divScore) AS ?avgDiversificationScore)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?cv)) - SUM(xsd:decimal(?c))) AS ?gain
    WHERE {
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?cv ;
               wm:cost ?c .
    }
    GROUP BY ?investor
  }
  OPTIONAL {
    ?health a wm:PortfolioHealth ;
            wm:healthOfInvestor ?investor ;
            wm:riskScore ?riskScore ;
            wm:diversificationScore ?divScore .
  }
  OPTIONAL {
    ?investor wm:hasTimeHorizon ?timeHorizon .
    ?timeHorizon rdfs:label ?timeHorizonLabel .
  }
}
GROUP BY ?timeHorizonLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?inv ;
      wm:liquidityScore ?liqScore .
  FILTER(?liqScore < 30)

  {
    SELECT ?inv (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain)
    WHERE {
      ?h a wm:PortfolioHolding ;
         wm:heldByInvestor ?inv ;
         wm:currentValue ?cv ;
         wm:cost ?c .
      BIND(xsd:decimal(?cv) - xsd:decimal(?c) AS ?gain)
    }
    GROUP BY ?inv
    HAVING (SUM(xsd:decimal(?gain)) < 0)
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?sf)) AS ?totalShortfall)
    WHERE {
      ?g a wm:InvestmentGoal ;
         wm:belongsToInvestor ?inv ;
         wm:shortfall ?sf .
    }
    GROUP BY ?inv
    HAVING (SUM(xsd:decimal(?sf)) > 0)
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?netCashFlow)
    WHERE {
      ?cf a wm:CashFlow ;
           wm:cashFlowOfInvestor ?inv ;
           wm:amount ?amt .
    }
    GROUP BY ?inv
    HAVING (SUM(xsd:decimal(?amt)) < 0)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       (AVG(?shortfallSum) AS ?avgShortfall)
       (AVG(?holdingValue) AS ?avgHoldingValue)
       (AVG(?maxAllocPct) AS ?avgAllocationPct)
       (AVG(?liquidityScore) AS ?avgLiquidityScore)
       (AVG(?diversificationScore) AS ?avgDiversificationScore)
WHERE {
  {
    SELECT ?investor (SUM(xsd:decimal(?shortfall)) AS ?shortfallSum)
    WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:shortfall ?shortfall ;
            wm:belongsToInvestor ?investor .
    } GROUP BY ?investor
  }
  {
    SELECT ?investor (SUM(xsd:decimal(?currVal)) AS ?holdingValue)
    WHERE {
      ?hold a wm:PortfolioHolding ;
            wm:currentValue ?currVal ;
            wm:heldByInvestor ?investor .
    } GROUP BY ?investor
  }
  {
    SELECT ?investor (MAX(xsd:decimal(?allocPct)) AS ?maxAllocPct)
    WHERE {
      ?alloc a wm:SectorAllocation ;
            wm:allocationPct ?allocPct ;
            wm:allocationOfInvestor ?investor .
    } GROUP BY ?investor
  }
  {
    SELECT ?investor (AVG(xsd:decimal(?liqScore)) AS ?liquidityScore)
           (AVG(xsd:decimal(?divScore)) AS ?diversificationScore)
    WHERE {
      ?health a wm:PortfolioHealth ;
              wm:liquidityScore ?liqScore ;
              wm:diversificationScore ?divScore ;
              wm:healthOfInvestor ?investor .
    } GROUP BY ?investor
  }
  ?investor a wm:Investor ;
            wm:timeHorizon ?timeHorizon .
}
GROUP BY ?timeHorizon
ORDER BY ?timeHorizon

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?month ?scenarioLabel (SUM(xsd:decimal(?amount)) AS ?netCashFlow)
WHERE {
  {
    SELECT DISTINCT ?invId WHERE {
      ?goal a wm:InvestmentGoal ;
            wm:investorId ?invId ;
            wm:progressPct ?progress .
      FILTER(xsd:decimal(?progress) < 25)
    }
  }
  ?cf a wm:CashFlow ;
      wm:amount ?amount ;
      wm:date ?date ;
      wm:hasCashFlowSource ?scenario ;
      wm:investorId ?invId .
  BIND(SUBSTR(?date,6,2) AS ?month)
  OPTIONAL { ?scenario rdfs:label ?scenarioLabel . }
}
GROUP BY ?month ?scenarioLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?category ?totalCashFlow ?avgAllocChange ?scenarioCount WHERE {
  {
    SELECT ?category (SUM(xsd:decimal(?amt)) AS ?totalCashFlow) WHERE {
      ?inv a wm:Investor ;
           wm:category ?category ;
           wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?category
  }
  {
    SELECT ?category (AVG(xsd:decimal(?chg)) AS ?avgAllocChange) (COUNT(DISTINCT ?scen) AS ?scenarioCount) WHERE {
      ?inv a wm:Investor ;
           wm:category ?category ;
           wm:hasScenarioRebalancing ?sr .
      ?sr wm:currentAllocationPct ?curr ;
          wm:newAllocationPct ?new ;
          wm:scenario ?scen .
      BIND (xsd:decimal(?new) - xsd:decimal(?curr) AS ?chg)
    }
    GROUP BY ?category
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId .
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?inv wm:hasCashFlow ?cf .
    ?cf wm:type ?cfType .
    FILTER(LCASE(STR(?cfType)) = "withdrawal")
  }

  FILTER EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold wm:returnsPct ?ret .
    FILTER(xsd:decimal(?ret) < 0)
  }

  FILTER EXISTS {
    ?inv wm:hasSectorAllocation ?alloc .
    ?alloc wm:allocationPct ?allocPct .
    FILTER(xsd:decimal(?allocPct) > 30)
  }

  FILTER EXISTS {
    ?inv wm:hasPortfolioHealth ?ph .
    ?ph wm:liquidityScore ?liq .
    FILTER(xsd:decimal(?liq) < 30)
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?catLabel
       (SUM(?shortfallSum) AS ?categoryShortfall)
       (SUM(?holdingSum) AS ?categoryHoldingValue)
       (SUM(?allocationSum) AS ?categoryAllocationPct)
       (AVG(?liquidityScore) AS ?avgLiquidityScore)
       (AVG(?diversificationScore) AS ?avgDiversificationScore)
WHERE {
  {
    SELECT ?investor ?cat (SUM(?shortfall) AS ?shortfallSum)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL { ?investor wm:hasCategory ?cat . }
      OPTIONAL {
        ?goal a wm:InvestmentGoal ;
              wm:belongsToInvestor ?investor ;
              wm:shortfall ?shortfall .
      }
    }
    GROUP BY ?investor ?cat
  }
  OPTIONAL {
    SELECT ?investor ?cat (SUM(?holdingValue) AS ?holdingSum)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL { ?investor wm:hasCategory ?cat . }
      ?holding a wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:currentValue ?holdingValue .
    }
    GROUP BY ?investor ?cat
  }
  OPTIONAL {
    SELECT ?investor ?cat (SUM(?allocationPct) AS ?allocationSum)
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL { ?investor wm:hasCategory ?cat . }
      ?alloc a wm:SectorAllocation ;
            wm:allocationOfInvestor ?investor ;
            wm:allocationPct ?allocationPct .
    }
    GROUP BY ?investor ?cat
  }
  OPTIONAL {
    SELECT ?investor ?cat ?liquidityScore ?diversificationScore
    WHERE {
      ?investor a wm:Investor .
      OPTIONAL { ?investor wm:hasCategory ?cat . }
      ?health a wm:PortfolioHealth ;
              wm:healthOfInvestor ?investor ;
              wm:liquidityScore ?liquidityScore ;
              wm:diversificationScore ?diversificationScore .
    }
  }
  OPTIONAL { ?cat rdfs:label ?catLabel . }
}
GROUP BY ?cat ?catLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:sectorFocus ?sectorFocus .
  OPTIONAL { ?inv wm:investorName ?investorName . }
  FILTER(CONTAINS(LCASE(STR(?sectorFocus)), "real estate"))
  FILTER NOT EXISTS {
    ?inv wm:hasHolding ?holding .
    ?holding wm:hasSector ?sector .
    ?sector rdfs:label ?sectorLabel .
    FILTER(CONTAINS(LCASE(STR(?sectorLabel)), "real estate"))
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?riskTol ?triggeredAction (SUM(xsd:decimal(?amt)) AS ?netCashFlow) (AVG(xsd:decimal(?sf)) AS ?avgGoalShortfall)
WHERE {
  ?sr a wm:ScenarioRebalancing ;
      wm:triggeredAction ?triggeredAction ;
      wm:scenarioRebalancingOfInvestor ?inv .
  OPTIONAL { ?inv wm:riskTolerance ?riskTol . }

  OPTIONAL {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?amt)
    WHERE {
      ?cf a wm:CashFlow ;
          wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amt .
    }
    GROUP BY ?inv
  }

  OPTIONAL {
    SELECT ?inv (AVG(xsd:decimal(?sf)) AS ?sf)
    WHERE {
      ?ig a wm:InvestmentGoal ;
          wm:belongsToInvestor ?inv ;
          wm:shortfall ?sf .
    }
    GROUP BY ?inv
  }
}
GROUP BY ?riskTol ?triggeredAction

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?segmentLabel (COALESCE(?totalCashFlow, 0) AS ?totalCashFlow) (COALESCE(?totalScenarioChange, 0) AS ?totalScenarioChange) (COALESCE(?scenarioCount, 0) AS ?scenarioCount)
WHERE {
  ?segment a wm:Segment .
  OPTIONAL {
    SELECT ?segment (SUM(xsd:decimal(?amount)) AS ?totalCashFlow)
    WHERE {
      ?inv wm:hasSegment ?segment .
      ?cf wm:cashFlowOfInvestor ?inv ;
          wm:amount ?amount .
    }
    GROUP BY ?segment
  }
  OPTIONAL {
    SELECT ?segment (SUM(xsd:decimal(?change)) AS ?totalScenarioChange) (COUNT(?sr) AS ?scenarioCount)
    WHERE {
      ?inv wm:hasSegment ?segment .
      ?sr wm:scenarioRebalancingOfInvestor ?inv ;
          wm:newAllocationPct ?new ;
          wm:currentAllocationPct ?cur .
      BIND (xsd:decimal(?new) - xsd:decimal(?cur) AS ?change)
    }
    GROUP BY ?segment
  }
  OPTIONAL { ?segment rdfs:label ?segmentLabel . }
}
ORDER BY ?segmentLabel

PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?timeHorizon
       ?avgAllocPct
       ?avgReturnPct
       ?totalCurrentValue
WHERE {
  {
    SELECT (LCASE(STR(?thLit)) AS ?timeHorizon) (AVG(xsd:decimal(?allocPct)) AS ?avgAllocPct)
    WHERE {
      ?inv a wm:Investor .
      OPTIONAL { ?inv wm:timeHorizon ?thLit . }
      ?inv wm:hasSectorAllocation ?alloc .
      ?alloc wm:allocationPct ?allocPct .
      FILTER(bound(?allocPct) && bound(?thLit))
    }
    GROUP BY ?thLit
  }
  {
    SELECT (LCASE(STR(?thLit2)) AS ?timeHorizon) (AVG(xsd:decimal(?retPct)) AS ?avgReturnPct) (SUM(xsd:decimal(?currVal)) AS ?totalCurrentValue)
    WHERE {
      ?inv a wm:Investor .
      OPTIONAL { ?inv wm:timeHorizon ?thLit2 . }
      ?inv wm:hasHolding ?hold .
      ?hold wm:returnsPct ?retPct .
      ?hold wm:currentValue ?currVal .
      FILTER(bound(?retPct) && bound(?currVal) && bound(?thLit2))
    }
    GROUP BY ?thLit2
  }
}
